(function(){var m=window.SITE_DATA_BY_DOMAIN=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]=m["image"]||{};d["algorithms"]=[{"id":"alg-nvfp4-dit-hybrid","name":"DiT NVFP4 混合精度量化","year":2024,"direction":"dir-step-distill-consistency","tier":"recent","problem":"DiT 主干权重与激活在 Blackwell 上仍以 BF16/FP8 存储，显存带宽与 Tensor Core 利用率受限，单张 B200 跑 1024² 采样时 batch 被显存卡死，无法吃满 NVFP4 峰值算力。","idea":"对线性层权重做 NVFP4（E2M1 + 两级微缩放）块量化，对激活保留 FP8 或 BF16，敏感层（首末 block、调制投影）走 FP8 回退，配合 Blackwell tcgen05 MMA 的混合精度通路一次前向完成。","how":"它解决的具体问题是：DiT 主干权重与激活在 Blackwell 上仍以 BF16/FP8 存储，显存带宽与 Tensor Core 利用率受限，单张 B200 跑 1024² 采样时 batch 被显存卡死，无法吃满 NVFP4 峰值算力。 机制按数据流顺序为：校准集跑 32–64 步前向，按 block 统计权重/激活的 per-group amax 与敏感度分数；权重按 16 元素一组打包为 NVFP4，附 FP8 per-group scale 与 FP32 二级 scale；激活在线量化到 FP8（E4M3），首末 block 与 adaLN 调制保持 BF16。 推理时 tcgen05 MMA 直接消费 NVFP4×FP8，累加器 FP32，反量化在 epilogue 融合；VAE 解码前把 latent 还原为 BF16，避免解码器数值漂移。核心量化关系可写为 $$w_q=\\mathrm{round}_{E2M1}\\!\\left(\\frac{w}{s_1 s_2}\\right),\\quad \\hat{w}=w_q\\cdot s_1\\cdot s_2$$，其中 $s_1$ 为 FP8 per-group scale、$s_2$ 为 FP32 二级 scale。","flow":["校准集跑 32–64 步前向，按 block 统计权重/激活的 per-group amax 与敏感度分数","权重按 16 元素一组打包为 NVFP4，附 FP8 per-group scale 与 FP32 二级 scale","激活在线量化到 FP8（E4M3），首末 block 与 adaLN 调制保持 BF16","推理时 tcgen05 MMA 直接消费 NVFP4×FP8，累加器 FP32，反量化在 epilogue 融合","VAE 解码前把 latent 还原为 BF16，避免解码器数值漂移"],"formula":"$$\\hat{W}_{g}=\\mathrm{dequant}\\big(s_{g}^{\\text{outer}}\\cdot s_{g}^{\\text{inner}}\\cdot Q_{4}(W_{g})\\big),\\quad \\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$$","pros":["权重显存降至 BF16 的 1/4，B200 上 1024² 采样的 batch 可提升 2–3 倍，直接抬高吞吐","NVFP4 两级缩放把 per-group 量化误差压到 FP8 同级，画质 FID 退化通常 <0.5"],"cons":["首末 block 与调制层必须回退，否则色彩偏移与结构崩坏明显，回退比例需逐模型校准","激活在线量化的 amax 统计引入额外 kernel，若与 attention 融合不好会吃掉 5–10% 时延收益"],"papers":["paper-fp4dit-towards-effective-floating-po-2025","paper-hq-dit-efficient-diffusion-transform-2024"],"successors":["alg-ptq4dit-block-calib"],"facts":["它解决的具体问题是：DiT 主干权重与激活在 Blackwell 上仍以 BF16/FP8 存储，显存带宽与 Tensor Core 利用率受限，单张 B200 跑 1024² 采样时 batch 被显存卡死，无法吃满 NVFP4 峰值算力。","机制按数据流顺序为：校准集跑 32–64 步前向，按 block 统计权重/激活的 per-group amax 与敏感度分数；权重按 16 元素一组打包为 NVFP4，附 FP8 per-group scale 与 FP32 二级 scale；激活在线量化到 FP8（E4M3），首末 block 与 adaLN 调制保持 BF16。","推理时 tcgen05 MMA 直接消费 NVFP4×FP8，累加器 FP32，反量化在 epilogue 融合；VAE 解码前把 latent 还原为 BF16，避免解码器数值漂移。核心量化关系可写为 $$w_q=\\mathrm{round}_{E2M1}\\!\\left(\\frac{w}{s_1 s_2}\\right),\\quad \\hat{w}=w_q\\cdot s_1\\cdot s_2$$，其中 $s_1$ 为 FP8 per-group scale、$s_2$ 为 FP32 二级 scale。","负载配方：请求形态为 1024² 单图采样，批大小受显存约束，权重显存降至 BF16 的 1/4 后 B200 上 batch 可提升 2–3 倍；SLO 以吞吐为主，具体时延数值未给出。","部署配方：硬件档位为单张 B200，量化采用 NVFP4 权重 × FP8 激活、FP32 累加器，敏感层（首末 block、调制投影）走 FP8 回退，回退比例需逐模型校准；KV 与并行拓扑细节未给出。","稳定性技巧：首末 block 与 adaLN 调制层必须回退到 FP8/BF16，否则色彩偏移与结构崩坏明显；激活在线量化的 amax 统计引入额外 kernel，若与 attention 融合不好会吃掉 5–10% 时延收益。","与相邻算法的差别：它只改数值格式与算子通路，不改采样步数与调度，因此可与步数蒸馏、CFG 批合并叠加；相比纯 FP8 量化，NVFP4 两级缩放把 per-group 量化误差压到 FP8 同级，画质 FID 退化通常 <0.5。","适用边界与规模上限：收益集中在显存带宽受限的大分辨率采样，1024² 下 batch 提升 2–3 倍；敏感层回退比例随模型增大而上升，回退过多会侵蚀显存收益，规模上限受校准集覆盖度与 kernel 融合质量约束。"],"anchors":["32–64 步","16 元素一组","1/4","2–3 倍","<0.5","5–10%"],"pitfalls":["首末 block 与调制层未回退时，NVFP4 权重的两级缩放误差会在高噪步被放大，表现为色彩偏移与结构崩坏，必须逐模型校准回退比例。","激活在线量化的 amax 统计若未与 attention 融合，会额外插入 kernel 并吃掉 5–10% 时延收益，抵消部分显存带宽红利。","VAE 解码前未把 latent 还原为 BF16 时，解码器数值漂移会导致细节糊化，量化收益被画质退化抵消。"]},{"id":"alg-fa3-blackwell-attn","name":"Blackwell 异步 FA3 注意力","year":2024,"direction":"dir-dit-quantization","tier":"recent","problem":"DiT 的全局注意力在 1024² 以上分辨率时序列长度 4k–16k，朴素 attention 的 HBM 读写成为主瓶颈，SM 利用率低且 KV 无法驻留。","idea":"用 FlashAttention-3 的 warp-specialized 生产者/消费者流水，把 QK^T 的 GEMM 与 softmax 重叠，在 Blackwell 上用 TMA 异步搬运 KV tile、FP8 做 QK^T 而 PV 保持高精度。","how":"它解决的具体问题是：DiT 的全局注意力在 1024² 以上分辨率时序列长度 4k–16k，朴素 attention 的 HBM 读写成为主瓶颈，SM 利用率低且 KV 无法驻留。 机制按数据流顺序为：按序列切 Q tile，KV 以 TMA 异步预取到 shared memory 双缓冲；QK^T 走 FP8 tcgen05 MMA，softmax 在寄存器内做 online 归一化并写回 FP32 累加器；softmax 结果转 FP16 与 V tile 做 PV GEMM，与下一 tile 的 QK^T 重叠。 跨 tile 合并按 online softmax 递推：$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$，其中 $m$ 为 running max、$\\ell$ 为归一化因子，最后统一除以归一化因子得到输出。","flow":["按序列切 Q tile，KV 以 TMA 异步预取到 shared memory 双缓冲","QK^T 走 FP8 tcgen05 MMA，softmax 在寄存器内做 online 归一化并写回 FP32 累加器","softmax 结果转 FP16 与 V tile 做 PV GEMM，与下一 tile 的 QK^T 重叠","按 online softmax 递推合并跨 tile 的部分和，最后统一除以归一化因子","输出写回 HBM 并直接喂给下一层 DiT block 的 LayerNorm"],"formula":"$$O_{i}=\\sum_{j}\\frac{\\exp(q_{i}k_{j}^{\\top}/\\sqrt{d}-m_{i})}{\\ell_{i}}v_{j},\\quad \\text{IO}\\propto \\frac{N^{2}d}{\\text{SRAM}},\\ \\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$","pros":["把 attention 的 HBM 流量从 O(N²) 降到 O(N·d)，16k 序列下时延可降 2–4 倍","FP8 QK^T 在 Blackwell 上吞吐翻倍，且 PV 保持 FP16 使画质几乎无损"],"cons":["FP8 QK^T 对 attention logit 动态范围敏感，需 per-head scaling，否则高分辨率细节糊","warp-specialized 流水对 head_dim 与 tile 形状挑剔，非 64/128 对齐的 DiT 变体需重写 kernel"],"papers":["paper-flashattention-3-fast-and-accurate-a-2024","paper-flashattention-2-faster-attention-wi-2023"],"successors":[],"facts":["它解决的具体问题是：DiT 的全局注意力在 1024² 以上分辨率时序列长度 4k–16k，朴素 attention 的 HBM 读写成为主瓶颈，SM 利用率低且 KV 无法驻留。","机制按数据流顺序为：按序列切 Q tile，KV 以 TMA 异步预取到 shared memory 双缓冲；QK^T 走 FP8 tcgen05 MMA，softmax 在寄存器内做 online 归一化并写回 FP32 累加器；softmax 结果转 FP16 与 V tile 做 PV GEMM，与下一 tile 的 QK^T 重叠。","跨 tile 合并按 online softmax 递推：$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$，其中 $m$ 为 running max、$\\ell$ 为归一化因子，最后统一除以归一化因子得到输出。","负载配方：请求形态为 1024² 以上分辨率、序列长度 4k–16k 的 DiT 采样，批大小与 SLO 数值未给出；16k 序列下时延可降 2–4 倍。","部署配方：硬件档位为 Blackwell，采用 warp-specialized 生产者/消费者流水与 TMA 异步搬运，QK^T 用 FP8、PV 保持 FP16 高精度，KV tile 驻留 shared memory 双缓冲；并行拓扑细节未给出。","稳定性技巧：FP8 QK^T 对 attention logit 动态范围敏感，需 per-head scaling，否则高分辨率细节糊；warp-specialized 流水对 head_dim 与 tile 形状挑剔，非 64/128 对齐的 DiT 变体需重写 kernel。","与相邻算法的差别：它把 attention 的 HBM 流量从 O(N²) 降到 O(N·d)，而 FlashAttention-2 的流水未针对 Blackwell 异步通路；FP8 只用于 QK^T、PV 保持 FP16，使画质几乎无损而吞吐翻倍。","适用边界与规模上限：收益随序列长度增长，16k 序列时延降 2–4 倍；head_dim 与 tile 需 64/128 对齐，非对齐变体需重写 kernel，规模上限受 shared memory 容量与双缓冲深度约束。"],"anchors":["4k–16k","16k","2–4 倍","64/128"],"pitfalls":["FP8 QK^T 缺少 per-head scaling 时，attention logit 动态范围溢出会导致高分辨率细节糊化，画质退化难以通过后处理挽回。","head_dim 或 tile 形状非 64/128 对齐的 DiT 变体直接套用 kernel 会触发重写或性能回退，warp-specialized 流水无法按预期重叠。","KV 双缓冲深度不足时 TMA 预取与 MMA 无法重叠，HBM 流量回落，16k 序列的时延收益被吃掉。"]},{"id":"alg-lcm-fewstep","name":"潜空间一致性少步采样","year":2023,"direction":"dir-cache-sparsity","tier":"recent","problem":"标准扩散需 20–50 步 UNet/DiT 前向，单张图端到端时延被步数线性放大，服务端 GPU 利用率与单位成本难以接受。","idea":"在 latent 空间蒸馏一致性模型，把任意时刻的 PF-ODE 轨迹点直接映射回 x0，用 4–8 步完成采样，并保留 CFG 蒸馏以省掉双 batch。","how":"它解决的具体问题是：标准扩散需 20–50 步 UNet/DiT 前向，单张图端到端时延被步数线性放大，服务端 GPU 利用率与单位成本难以接受。 机制按数据/梯度流顺序为：教师模型在 latent 上跑 PF-ODE 生成 $(x_t,x_0)$ 配对轨迹；学生网络以 $x_t$ 与 $t$ 为输入直接预测 $x_0$，损失为与教师 $x_0$ 的距离加一致性自洽项；蒸馏时把 CFG 引导尺度并入条件嵌入，学生单次前向替代双 batch。 核心公式为一致性映射 $$f_\\theta(x_t,t)\\approx x_0,\\quad \\mathcal{L}=\\mathbb{E}\\left[\\|f_\\theta(x_t,t)-x_0\\|^2\\right]+\\lambda\\,\\mathcal{L}_{\\mathrm{cons}}$$，其中 $x_0$ 为教师 PF-ODE 终点、$\\lambda$ 为自洽项权重。","flow":["教师模型在 latent 上跑 PF-ODE 生成 (x_t, x_0) 配对轨迹","学生网络以 x_t 与 t 为输入直接预测 x_0，损失为与教师 x_0 的距离加一致性自洽项","蒸馏时把 CFG 引导尺度并入条件嵌入，学生单次前向替代双 batch","推理按 4–8 个离散时间点跳步，每步一次 DiT 前向加一次 scheduler 更新","末端 latent 送 VAE 解码，跳过冗余的高噪步"],"formula":"$$\\mathcal{L}_{\\text{cons}}=\\mathbb{E}_{t}\\big\\|f_{\\theta}(x_{t},t)-f_{\\theta}(x_{t'},t')\\big\\|^{2},\\quad T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$","pros":["步数从 30 降到 4–8，端到端时延降 4–8 倍，且无需改推理框架","CFG 蒸馏后单次前向替代双 batch，显存与算力同时减半"],"cons":["少步采样对文本复杂组合与细粒度文字生成退化明显，需按业务分层选择步数","蒸馏学生绑定教师架构，换底模需重训，冷启动成本高"],"papers":["paper-latent-consistency-models-synthesizi-2023","paper-consistency-models-2023"],"successors":[],"facts":["它解决的具体问题是：标准扩散需 20–50 步 UNet/DiT 前向，单张图端到端时延被步数线性放大，服务端 GPU 利用率与单位成本难以接受。","机制按数据/梯度流顺序为：教师模型在 latent 上跑 PF-ODE 生成 $(x_t,x_0)$ 配对轨迹；学生网络以 $x_t$ 与 $t$ 为输入直接预测 $x_0$，损失为与教师 $x_0$ 的距离加一致性自洽项；蒸馏时把 CFG 引导尺度并入条件嵌入，学生单次前向替代双 batch。","核心公式为一致性映射 $$f_\\theta(x_t,t)\\approx x_0,\\quad \\mathcal{L}=\\mathbb{E}\\left[\\|f_\\theta(x_t,t)-x_0\\|^2\\right]+\\lambda\\,\\mathcal{L}_{\\mathrm{cons}}$$，其中 $x_0$ 为教师 PF-ODE 终点、$\\lambda$ 为自洽项权重。","负载配方：请求形态为 latent 空间文生图，推理按 4–8 个离散时间点跳步，每步一次 DiT 前向加一次 scheduler 更新；批大小与 SLO 数值未给出，端到端时延降 4–8 倍。","部署配方：硬件档位与并行拓扑未给出；CFG 蒸馏后单次前向替代双 batch，显存与算力同时减半；末端 latent 送 VAE 解码，跳过冗余的高噪步。","稳定性技巧：少步采样对文本复杂组合与细粒度文字生成退化明显，需按业务分层选择步数；蒸馏学生绑定教师架构，换底模需重训，冷启动成本高。","与相邻算法的差别：它改的是采样步数与 CFG 结构，而非数值格式或注意力 kernel，因此可与 NVFP4 量化、FA3 注意力叠加；相比标准扩散的 20–50 步，4–8 步把时延降 4–8 倍且无需改推理框架。","适用边界与规模上限：适合对细粒度文字与复杂组合要求不高的业务分层；步数降到 4–8 后画质退化随文本复杂度上升，规模上限受教师架构绑定与重训成本约束。"],"anchors":["20–50 步","4–8 步","4–8 倍"],"pitfalls":["少步采样在文本复杂组合与细粒度文字生成上退化明显，若不分层选择步数，业务画质投诉会集中出现在长 prompt 场景。","蒸馏学生绑定教师架构，换底模必须重训，冷启动成本高，直接复用旧学生会导致分布错配与画质崩坏。","CFG 蒸馏把引导尺度并入条件嵌入后，引导强度调节空间收窄，极端尺度下易出现过饱和或结构塌陷。"]},{"id":"alg-cfg-batch-merge","name":"CFG 批合并与条件缓存","year":2023,"direction":"dir-serving-scheduling","tier":"recent","problem":"Classifier-Free Guidance 每步要跑条件与无条件两次前向，算力翻倍且两次前向的 KV/激活无法共享，batch 调度被拆碎。","idea":"把条件与无条件样本在 batch 维拼接成一次前向，文本编码与 KV 只算一次并缓存，输出按通道做引导组合，减少 kernel launch 与显存往返。","how":"解决 Classifier-Free Guidance 每步需跑条件与无条件两次前向的问题：显存与算力翻倍，服务端 batch 被 CFG 撕裂成两半，吞吐与显存利用率双低；批合并把两次 kernel launch 合并为一次前向。 机制按数据流顺序：请求队列取出 prompt，同时构造空 prompt 与条件 prompt 的 embedding；两路 latent 在 batch 维 concat 成 2B 输入张量送入 DiT；DiT 单次前向产出 2B 的 noise 预测并按前半/后半切分；输出端按 guidance scale 线性组合合并为 B，进入 scheduler 更新 latent，下一 step 重复 concat。 核心公式为输出端合并：$$\\epsilon = \\epsilon_{\\mathrm{uncond}} + s\\,(\\epsilon_{\\mathrm{cond}} - \\epsilon_{\\mathrm{uncond}})$$，其中 $\\epsilon_{\\mathrm{uncond}}$ 为前半批空 prompt 的 noise 预测，$\\epsilon_{\\mathrm{cond}}$ 为后半批条件 prompt 的预测，$s$ 为 guidance scale，合并结果 $\\epsilon$ 送入 scheduler。","flow":["请求到达后先跑一次文本编码器，缓存 prompt embedding 与负向 embedding","每步把 [cond; uncond] 在 batch 维 cat 成 2B，一次 DiT 前向","输出按前半/后半切片，做 x = x_u + s·(x_c − x_u) 的引导组合","组合结果写回单份 latent，进入下一步 scheduler","文本 embedding 跨步复用，避免每步重算 T5/CLIP"],"formula":"$$\\hat{x}=x_{\\text{uncond}}+s\\,(x_{\\text{cond}}-x_{\\text{uncond}}),\\quad \\text{Throughput}\\approx\\frac{2B}{t_{\\text{fwd}}(2B)}\\ \\text{vs}\\ \\frac{B}{t_{\\text{fwd}}(B)}$$","pros":["两次前向合并为一次大 batch，Blackwell 上大 batch 的 MMA 利用率更高，实测吞吐提升 1.3–1.6 倍","文本编码只算一次，长 prompt 场景省下可观的 prefill 开销"],"cons":["batch 翻倍使激活显存翻倍，高分辨率下可能触发 OOM，需要与量化/分块配合","引导尺度 s 大时数值动态范围变大，低精度下易溢出，需保持组合在 FP32"],"papers":["paper-photorealistic-text-to-image-diffusi-2022","paper-sdxl-improving-latent-diffusion-mode-2023"],"successors":["alg-mx-mixed-precision-dit"],"facts":["解决 Classifier-Free Guidance 每步需跑条件与无条件两次前向的问题：显存与算力翻倍，服务端 batch 被 CFG 撕裂成两半，吞吐与显存利用率双低；批合并把两次 kernel launch 合并为一次前向。","机制按数据流顺序：请求队列取出 prompt，同时构造空 prompt 与条件 prompt 的 embedding；两路 latent 在 batch 维 concat 成 2B 输入张量送入 DiT；DiT 单次前向产出 2B 的 noise 预测并按前半/后半切分；输出端按 guidance scale 线性组合合并为 B，进入 scheduler 更新 latent，下一 step 重复 concat。","核心公式为输出端合并：$$\\epsilon = \\epsilon_{\\mathrm{uncond}} + s\\,(\\epsilon_{\\mathrm{cond}} - \\epsilon_{\\mathrm{uncond}})$$，其中 $\\epsilon_{\\mathrm{uncond}}$ 为前半批空 prompt 的 noise 预测，$\\epsilon_{\\mathrm{cond}}$ 为后半批条件 prompt 的预测，$s$ 为 guidance scale，合并结果 $\\epsilon$ 送入 scheduler。","负载配方：请求形态为在线文生图，批大小按 2B 组织，B 受显存峰值约束；SLO 以单请求时延为主，合并后 kernel launch 与调度开销减半，GEMM 的 M 维更饱满，Tensor Core 利用率高于两次小 batch。","部署配方：硬件档位为单卡或张量并行 GPU；量化可与 FP8/FP4 叠加，concat 后的 2B 张量按同一权重计算；显存峰值翻倍，高分辨率/大 DiT 下可能触发 OOM，需配合分块或 offload 把峰值压回预算内。","稳定性技巧：concat 顺序必须固定为前半 uncond、后半 cond，切分索引与合并公式一一对应，否则 guidance 方向反转；guidance scale 合并发生在输出端，无法在中途按样本动态调 $s$，需在请求入口按业务分层预设。","与相邻算法的差别：串行双前向每步两次 kernel launch、两次小 batch GEMM；批合并把两路拼成一次前向，调度开销减半但显存峰值翻倍；与 CFG 蒸馏（把 guidance 蒸进单分支）相比，批合并不改模型结构、无训练成本，但显存代价更高。","适用边界与规模上限：适合显存充裕、batch 可拼到 2B 且 DiT 规模中等的在线服务；高分辨率大 DiT 下显存峰值翻倍易 OOM，需分块或 offload；无法按样本动态调 guidance scale，灵活性下降；规模上限由单卡显存峰值与并行拓扑决定。"],"anchors":["2023","paper-photorealistic-text-to-image-diffusi-2022","paper-sdxl-improving-latent-diffusion-mode-2023"],"pitfalls":["高分辨率大 DiT 下 concat 后 2B 张量使显存峰值翻倍，未配合分块或 offload 时直接触发 OOM，服务端 batch 被迫回退到串行双前向。","concat 顺序或切分索引与合并公式错位，guidance 方向反转，输出画面过饱和或语义偏离 prompt，且难以从日志定位。","guidance scale 固定在输出端合并，无法按样本动态调 $s$，长尾请求与批量请求共用同一 $s$ 时画质与语义对齐难以兼顾。"]},{"id":"alg-feature-cache-skip","name":"特征缓存与块级跳步","year":2025,"direction":"dir-vae-latent-codec","tier":"recent","problem":"相邻扩散步的 DiT block 输出高度相似，逐步全量计算浪费算力，尤其在高步数教师模型与视频多帧场景下时延被线性放大。","idea":"按 block 统计相邻步残差贡献度，对贡献低于阈值的 block 直接复用上一步输出，仅对高贡献 block 重算，并用残差补偿抑制误差累积。","how":"问题定位：相邻扩散步的 DiT block 输出高度相似，逐步全量前向使算力随步数线性放大；高步数教师模型与视频多帧场景下时延被进一步放大，成为端到端瓶颈。 机制按数据流顺序：先预热若干步，逐 block 记录相邻步输出差异作为贡献分数；按分数排序，低分 block 标记为可缓存、高分 block 保留计算；推理时缓存 block 读上一步 feature，计算 block 正常前向。 残差补偿：对缓存 block 施加轻量残差修正（缩放或低秩补偿）以对齐分布，抑制误差累积；每 N 步重新评估贡献分数，防止误差随步数漂移。","flow":["预热若干步，记录每个 block 输出的步间差异作为贡献分数","按分数排序，低分 block 标记为可缓存，高分 block 保留计算","推理时缓存 block 读上一步 feature，计算 block 正常前向","对缓存 block 施加轻量残差修正（如缩放或低秩补偿）以对齐分布","每 N 步重新评估贡献分数，防止误差漂移"],"formula":"$$\\hat{h}_{l}^{t}=h_{l}^{t-1}+\\alpha_{l}\\,\\Delta_{l}^{t},\\quad \\text{Skip if }\\|\\Delta_{l}^{t}\\|<\\tau_{l},\\quad \\text{Speedup}\\approx\\frac{L}{L_{\\text{compute}}}$$","pros":["无需重训，直接插到现有 DiT 推理管线，典型可省 30–50% block 计算","与少步蒸馏正交，叠加后进一步压低端到端时延"],"cons":["缓存误差在少步采样下更易累积，纹理细节与文字区域先崩","贡献分数依赖 prompt 与分辨率，跨业务需重新校准阈值，否则画质不稳"],"papers":["paper-corgi-contribution-guided-block-wise-2025","paper-sortblock-similarity-aware-feature-r-2025"],"successors":["alg-mixed-res-serve"],"facts":["问题定位：相邻扩散步的 DiT block 输出高度相似，逐步全量前向使算力随步数线性放大；高步数教师模型与视频多帧场景下时延被进一步放大，成为端到端瓶颈。","机制按数据流顺序：先预热若干步，逐 block 记录相邻步输出差异作为贡献分数；按分数排序，低分 block 标记为可缓存、高分 block 保留计算；推理时缓存 block 读上一步 feature，计算 block 正常前向。","残差补偿：对缓存 block 施加轻量残差修正（缩放或低秩补偿）以对齐分布，抑制误差累积；每 N 步重新评估贡献分数，防止误差随步数漂移。","核心公式：$$s_l=\\frac{\\|h_l^{(t)}-h_l^{(t-1)}\\|_2}{\\|h_l^{(t-1)}\\|_2},\\quad h_l^{(t)}=\\begin{cases}\\alpha_l h_l^{(t-1)}+\\Delta_l & s_l<\\tau\\\\ \\mathrm{Block}_l(h_{l-1}^{(t)}) & s_l\\ge\\tau\\end{cases}$$ 其中 $s_l$ 为第 $l$ 个 block 的步间相对残差贡献分数，$\\tau$ 为缓存阈值，$\\alpha_l$ 为缩放补偿系数，$\\Delta_l$ 为低秩残差项。","负载配方：请求形态为文生图/视频多帧的批量采样，批大小按显存档位取 1–8；SLO 以 P99 端到端时延为主，典型可省 30–50% block 计算，与少步蒸馏正交叠加后进一步压低时延。","部署配方：无需重训，直接插入现有 DiT 推理管线；硬件档位按显存选卡，量化可与 FP8/NVFP4 叠加；缓存 feature 常驻显存，需按 block 数×分辨率×批大小预留容量，KV 概念不适用。","稳定性技巧与失败模式：阈值需按 prompt 与分辨率校准；少步采样下缓存误差更易累积，纹理细节与文字区域先崩；跨业务复用阈值会导致画质不稳，需按业务重新标定。","与相邻算法差别：区别于少步蒸馏（改权重）与量化（改数值精度），本方法不改模型参数、只改前向计算图，属训练-free 的推理期跳步；与块级稀疏注意力不同，它跳过的是整 block 计算而非 token 交互。","适用边界与规模上限：适合高步数教师模型与视频多帧等步间相似度高的场景；步数过少（如 4–8 步）时相似度下降、收益收窄；分辨率越高、block 越多，缓存显存开销越大，规模上限受单卡显存约束。"],"anchors":["30–50% block 计算","每 N 步重新评估贡献分数"],"pitfalls":["少步采样下缓存误差逐步累积，纹理与文字区域先出现模糊或笔画断裂，且难以通过后处理修复。","贡献分数依赖 prompt 与分辨率，跨业务直接复用阈值会造成部分请求画质骤降，需逐业务重新校准。","缓存 feature 常驻显存，高分辨率大批量时显存占用接近全量计算，可能抵消吞吐收益。"]},{"id":"alg-stage-serving-pipeline","name":"阶段级扩散服务流水","year":2025,"direction":"dir-video-streaming","tier":"recent","problem":"文本编码、DiT 去噪、VAE 解码的算力与显存特征差异大，单体部署导致 GPU 在 VAE 阶段空转、在文本编码阶段被小 kernel 拖慢，SLO 抖动。","idea":"把扩散管线拆成编码/去噪/解码三个阶段独立部署，按阶段做 batch 与并行策略，阶段间用 latent 队列解耦，按 SLO 做背压与副本弹性。","how":"问题定位：文本编码、DiT 去噪、VAE 解码三阶段算力与显存特征差异大，单体部署使 GPU 在 VAE 阶段空转、在文本编码阶段被小 kernel 拖慢，SLO 抖动明显。 机制按数据流顺序：请求进网关后文本编码阶段批量编码 prompt 并写 latent 队列；去噪阶段按分辨率与步数分池，从队列取 latent 做多步 DiT 前向；去噪完成的 latent 进解码队列，VAE 阶段按 tile 并行解码。 调度与背压：各阶段暴露队列深度与 P99 时延，调度器按 SLO 扩缩副本；过载时按优先级丢弃或降分辨率，保证尾延迟；阶段间用 latent 队列解耦，实现异步流水。","flow":["请求进入网关，文本编码阶段批量编码 prompt 并写 latent 队列","去噪阶段按分辨率与步数分池，从队列取 latent 做多步 DiT 前向","去噪完成的 latent 进入解码队列，VAE 阶段按 tile 并行解码","各阶段暴露队列深度与 P99 时延，调度器按 SLO 扩缩副本","过载时按优先级丢弃或降分辨率，保证尾延迟"],"formula":"$$\\text{SLO}:\\ P\\big(T_{\\text{enc}}+T_{\\text{denoise}}+T_{\\text{dec}}\\le \\tau\\big)\\ge 1-\\epsilon,\\quad \\text{Replicas}_{s}\\propto\\frac{\\lambda_{s}\\,\\bar{t}_{s}}{\\text{target util}}$$","pros":["各阶段独立 batch，VAE 不再被去噪 batch 绑架，整机吞吐提升 1.5–2 倍","阶段级背压让尾延迟可控，SLO 达标率显著优于单体部署"],"cons":["阶段间 latent 传输引入额外显存拷贝与网络开销，跨节点时更明显","多副本弹性带来冷启动与显存碎片，调度器复杂度上升"],"papers":["paper-tridentserve-a-stage-level-serving-s-2025","paper-genserve-efficient-co-serving-of-het-2026"],"successors":[],"facts":["问题定位：文本编码、DiT 去噪、VAE 解码三阶段算力与显存特征差异大，单体部署使 GPU 在 VAE 阶段空转、在文本编码阶段被小 kernel 拖慢，SLO 抖动明显。","机制按数据流顺序：请求进网关后文本编码阶段批量编码 prompt 并写 latent 队列；去噪阶段按分辨率与步数分池，从队列取 latent 做多步 DiT 前向；去噪完成的 latent 进解码队列，VAE 阶段按 tile 并行解码。","调度与背压：各阶段暴露队列深度与 P99 时延，调度器按 SLO 扩缩副本；过载时按优先级丢弃或降分辨率，保证尾延迟；阶段间用 latent 队列解耦，实现异步流水。","核心公式：$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$ 其中 $Q_k$ 为第 $k$ 阶段队列深度，$\\lambda_k$ 为该阶段吞吐，$B_k$ 为批大小，$T_k^{\\mathrm{svc}}$ 为单批服务时间，端到端时延由最慢阶段决定。","负载配方：请求形态为混合分辨率文生图，批大小按阶段独立设定（编码阶段大批、去噪阶段按分辨率分池、VAE 阶段按 tile 并行）；SLO 以 P99 尾延迟与达标率为指标，整机吞吐提升 1.5–2 倍。","部署配方：三阶段独立部署，硬件档位可按阶段异构（编码用低算力卡、去噪用高算力卡、解码用大显存卡）；并行拓扑为阶段内数据并行+阶段间流水；量化按阶段选 FP8/NVFP4；latent 队列需显存与网络缓冲。","稳定性技巧与失败模式：阶段间 latent 传输引入额外显存拷贝与网络开销，跨节点更明显；多副本弹性带来冷启动与显存碎片，调度器复杂度上升；队列积压需背压防止雪崩。","与相邻算法差别：区别于单体部署与 patch 级调度，本方法按管线阶段切分而非按空间切分；与连续批处理（continuous batching）互补，前者解决阶段异构、后者解决请求到达异构。","适用边界与规模上限：适合多阶段管线长、阶段资源需求差异大的服务；阶段数越多、跨节点传输越多，收益被通信开销侵蚀；小规模单卡部署下拆分收益有限，规模上限受队列缓冲与调度器容量约束。"],"anchors":["1.5–2 倍","P99"],"pitfalls":["阶段间 latent 跨节点传输的显存拷贝与网络开销可能吃掉吞吐收益，尤其在高分辨率 latent 下更明显。","多副本弹性扩缩引发冷启动与显存碎片，调度器在负载突增时可能做出滞后决策导致 SLO 违约。","队列积压缺乏背压时，上游阶段持续灌入会造成下游 OOM 或长尾请求堆积。"]},{"id":"alg-mixed-resolution-serve","name":"混合分辨率补丁调度","year":2025,"direction":"dir-step-distill-consistency","tier":"recent","problem":"高分辨率请求与低分辨率请求混跑时，统一按最高分辨率分配显存与算力，导致低分辨率请求被拖慢、GPU 利用率与 SLO 双输。","idea":"把图像切成 patch，按内容复杂度与请求 SLO 分配不同分辨率与步数预算，patch 级调度器把同分辨率 patch 聚成 batch，跨请求共享 GPU。","how":"问题定位：高分辨率与低分辨率请求混跑时统一按最高分辨率分配显存与算力，低分辨率请求被拖慢，GPU 利用率与 SLO 双输。 机制按数据流顺序：请求解析后按目标分辨率与 SLO 切 patch 并标注预算；调度器按分辨率/步数把 patch 聚成同质 batch 送 DiT 前向；低复杂度 patch 走低分辨率或少步，高复杂度 patch 保留全预算。 拼回与降级：patch 结果按坐标拼回完整 latent 送 VAE 解码；队列按 SLO 优先级重排，超时 patch 降级处理，保证尾延迟。","flow":["请求解析后按目标分辨率与 SLO 切 patch，标注每 patch 的预算","调度器按分辨率/步数把 patch 聚成同质 batch，送 DiT 前向","低复杂度 patch 走低分辨率或少步，高复杂度 patch 保留全预算","patch 结果按坐标拼回完整 latent，送 VAE 解码","队列按 SLO 优先级重排，超时 patch 降级处理"],"formula":"$$\\text{Cost}=\\sum_{p}N_{p}\\,t_{\\text{step}}(r_{p}),\\quad \\text{Util}=\\frac{\\sum_{p}\\text{FLOPs}_{p}}{\\text{peak}\\cdot T_{\\text{wall}}}$$","pros":["patch 级异构 batch 让 GPU 始终有活干，混合负载下吞吐提升 1.4–1.8 倍","按 SLO 分配预算，尾延迟与画质可按业务分级"],"cons":["patch 拼接处易出现接缝，需重叠与后处理，增加解码开销","调度器需维护 patch 元数据与优先级，工程复杂度高"],"papers":["paper-patchedserve-a-patch-management-fram-2025","paper-hieredit-region-aware-hierarchical-d-2026"],"successors":[],"facts":["问题定位：高分辨率与低分辨率请求混跑时统一按最高分辨率分配显存与算力，低分辨率请求被拖慢，GPU 利用率与 SLO 双输。","机制按数据流顺序：请求解析后按目标分辨率与 SLO 切 patch 并标注预算；调度器按分辨率/步数把 patch 聚成同质 batch 送 DiT 前向；低复杂度 patch 走低分辨率或少步，高复杂度 patch 保留全预算。","拼回与降级：patch 结果按坐标拼回完整 latent 送 VAE 解码；队列按 SLO 优先级重排，超时 patch 降级处理，保证尾延迟。","核心公式：$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$ 其中 $\\mathrm{budget}_p$ 为 patch $p$ 的分辨率/步数预算，$c_p$ 为内容复杂度，$t_{\\mathrm{wait}}$ 为排队时间，$t_{\\mathrm{unit}}$ 为单位步时延，$r_{\\min},r_{\\max}$ 为预算上下界。","负载配方：请求形态为混合分辨率批量文生图，批大小按同质 patch 组聚合；SLO 按业务分级，混合负载下吞吐提升 1.4–1.8 倍，尾延迟与画质可按业务分级。","部署配方：patch 级调度器维护元数据与优先级，硬件档位按显存选卡，量化可与 FP8/NVFP4 叠加；patch 级 batch 需按分辨率对齐显存，VAE 解码按 tile 并行。","稳定性技巧与失败模式：patch 拼接处易出现接缝，需重叠与后处理，增加解码开销；调度器需维护 patch 元数据与优先级，工程复杂度高；复杂度估计偏差会导致预算分配失准。","与相邻算法差别：区别于阶段级流水（按管线阶段切分）与 VAE 分块（仅解码期切块），本方法在去噪前就按 patch 分配异构预算，属请求内空间异构调度。","适用边界与规模上限：适合高低分辨率混合、内容复杂度差异大的服务；patch 过小会增加调度与拼接开销，patch 过大则异构收益收窄；规模上限受调度器元数据容量与拼接后处理算力约束。"],"anchors":["1.4–1.8 倍"],"pitfalls":["patch 拼接处重叠不足或权重设计不当会出现可见接缝与色带，后处理开销抵消吞吐收益。","复杂度估计偏差导致低复杂度 patch 预算过高或高复杂度 patch 预算过低，画质与 SLO 同时受损。","patch 元数据与优先级队列在高并发下膨胀，调度器成为 CPU 侧瓶颈。"]},{"id":"alg-vae-tile-decode","name":"VAE 分块并行解码","year":2021,"direction":"dir-dit-quantization","tier":"classic","problem":"高分辨率 latent 送 VAE 解码时激活显存爆炸，单张 2048² 图像解码可占数十 GB，成为端到端吞吐的显存瓶颈。","idea":"把 latent 切成带重叠的 tile，逐 tile 解码后按重叠区做加权融合，配合 FP16 解码与 kernel 融合降低峰值显存。","how":"问题定位：高分辨率 latent 送 VAE 解码时激活显存爆炸，单张 2048² 图像解码可占数十 GB，成为端到端吞吐的显存瓶颈。 机制按数据流顺序：latent 按固定 tile 大小切分，边界留重叠像素；逐 tile 送 VAE 解码器，激活峰值限制在单 tile 内；重叠区按距离权重线性融合消除接缝；结果写回输出缓冲并释放 tile 激活。 收尾校正：全部 tile 完成后做一次色彩/亮度一致性校正，消除 tile 间分布差异；配合 FP16 解码与 kernel 融合进一步降低峰值显存。","flow":["latent 按固定 tile 大小切分，边界留重叠像素","逐 tile 送 VAE 解码器，激活峰值限制在单 tile 内","重叠区按距离权重做线性融合，消除接缝","解码结果写回输出缓冲，释放 tile 激活","全部 tile 完成后做一次色彩/亮度一致性校正"],"formula":"$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}},\\quad \\hat{x}=\\frac{\\sum_{i}w_{i}\\,D(\\text{tile}_{i})}{\\sum_{i}w_{i}}$$","pros":["峰值显存从全图降到单 tile，2048² 解码可在单卡完成","tile 间可并行，多 stream 下解码时延随 tile 数近线性下降"],"cons":["重叠区融合引入额外计算与接缝风险，权重设计不当会出现色带","tile 边界处感受野截断，高频细节可能不一致"],"papers":["paper-high-resolution-image-synthesis-with-2021","paper-sdxl-improving-latent-diffusion-mode-2023"],"successors":["alg-lcm-few-step"],"facts":["问题定位：高分辨率 latent 送 VAE 解码时激活显存爆炸，单张 2048² 图像解码可占数十 GB，成为端到端吞吐的显存瓶颈。","机制按数据流顺序：latent 按固定 tile 大小切分，边界留重叠像素；逐 tile 送 VAE 解码器，激活峰值限制在单 tile 内；重叠区按距离权重线性融合消除接缝；结果写回输出缓冲并释放 tile 激活。","收尾校正：全部 tile 完成后做一次色彩/亮度一致性校正，消除 tile 间分布差异；配合 FP16 解码与 kernel 融合进一步降低峰值显存。","核心公式：$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)},\\quad w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$ 其中 $\\hat{x}(u)$ 为像素 $u$ 的融合输出，$D_i(u)$ 为第 $i$ 个 tile 的解码结果，$\\mathcal{N}(u)$ 为覆盖 $u$ 的 tile 集合，$c_i$ 为 tile 中心，$\\sigma$ 为重叠区权重带宽。","负载配方：请求形态为高分辨率单图或批量图，批大小按单 tile 显存上限设定；SLO 以解码时延为主，tile 间可并行，多 stream 下解码时延随 tile 数近线性下降。","部署配方：硬件档位按单 tile 峰值显存选卡，2048² 解码可在单卡完成；并行拓扑为 tile 级多 stream；量化用 FP16 解码并配合 kernel 融合；无需 KV 缓存。","稳定性技巧与失败模式：重叠区融合引入额外计算与接缝风险，权重设计不当会出现色带；tile 边界处感受野截断，高频细节可能不一致；tile 过小则重叠占比高、算力浪费。","与相邻算法差别：区别于阶段级流水（按管线阶段切分）与 patch 级调度（去噪前切分），本方法仅在 VAE 解码期做空间切块，不改去噪计算图；与整图解码相比以重叠计算换显存。","适用边界与规模上限：适合高分辨率图像与视频帧解码的显存受限场景；tile 越小显存越省但重叠开销越大，规模上限受单 tile 感受野与融合权重设计约束。"],"anchors":["2048²","数十 GB","FP16"],"pitfalls":["重叠区权重设计不当会在 tile 边界产生色带或亮度跳变，且难以用全局校正完全消除。","tile 边界感受野截断导致高频细节不一致，文字与细纹理处出现断裂。","tile 过小使重叠区占比升高，融合计算与显存拷贝开销抵消显存收益。"]},{"id":"alg-rectified-flow-sampler","name":"整流流直线采样器","year":2022,"direction":"dir-cache-sparsity","tier":"recent","problem":"DDPM/DDIM 的采样轨迹弯曲，少步离散化误差大，步数一降画质就崩，且 scheduler 与模型绑定难以跨模型复用。","idea":"用 rectified flow 把概率路径拉直成直线插值，训练速度场沿直线恒定，推理用 Euler/中点法大步长积分，少步误差显著降低。","how":"它针对的是 DDPM/DDIM 采样轨迹弯曲、少步离散化误差大的问题：步数一降画质就崩，且 scheduler 与模型绑定、难以跨模型复用。整流流把概率路径拉直成直线插值，使大步长积分误差变小，从而在 4–8 步量级维持画质。 训练阶段按数据流顺序：取真实样本 $x_0$ 与高斯噪声 $\\varepsilon$，在时间 $t\\in[0,1]$ 上做直线插值得到 $x_t=(1-t)x_0+t\\varepsilon$，令网络回归从 $x_0$ 指向 $x_1=\\varepsilon$ 的恒定速度场，监督目标为 $v=x_1-x_0$，即噪声减样本。 推理阶段从纯噪声 $x_1$ 出发，按离散时间点 $t_k$ 前向计算速度场 $v_\\theta(x_k,t_k)$，再用 Euler 更新 $x_{k+1}=x_k+\\Delta t\\,v_\\theta(x_k,t_k)$；若用二阶中点法，则先取半步预测再校正，单步需两次前向。末端 latent 送 VAE 解码。","flow":["训练时在 x0 与噪声间做直线插值 x_t=(1−t)x0+t·ε，回归速度场 v=x1−x0","推理从纯噪声出发，按离散时间点 t_k 计算速度场","用 Euler 或二阶中点法沿直线更新 x_{k+1}=x_k+Δv","少步（4–8 步）即可收敛，末端 latent 送 VAE","可叠加 CFG 与少步蒸馏进一步压步数"],"formula":"$$x_{t}=(1-t)\\,x_{0}+t\\,\\epsilon,\\quad \\frac{dx}{dt}=v_{\\theta}(x_{t},t),\\quad x_{k+1}=x_{k}+\\Delta t\\,v_{\\theta}(x_{k},t_{k})$$","pros":["直线轨迹让大步长积分误差小，20 步可压到 8 步且画质稳定","速度场形式统一，scheduler 可跨模型复用，工程实现简单"],"cons":["直线假设在复杂条件（多物体、文字）下不严格成立，少步仍会丢细节","二阶积分需两次前向，单步成本翻倍，需权衡步数与每步开销"],"papers":["paper-rectified-flow-a-marginal-preserving-2022","paper-scaling-rectified-flow-transformers-2024"],"successors":["alg-flow-matching-sampler"],"facts":["它针对的是 DDPM/DDIM 采样轨迹弯曲、少步离散化误差大的问题：步数一降画质就崩，且 scheduler 与模型绑定、难以跨模型复用。整流流把概率路径拉直成直线插值，使大步长积分误差变小，从而在 4–8 步量级维持画质。","训练阶段按数据流顺序：取真实样本 $x_0$ 与高斯噪声 $\\varepsilon$，在时间 $t\\in[0,1]$ 上做直线插值得到 $x_t=(1-t)x_0+t\\varepsilon$，令网络回归从 $x_0$ 指向 $x_1=\\varepsilon$ 的恒定速度场，监督目标为 $v=x_1-x_0$，即噪声减样本。","推理阶段从纯噪声 $x_1$ 出发，按离散时间点 $t_k$ 前向计算速度场 $v_\\theta(x_k,t_k)$，再用 Euler 更新 $x_{k+1}=x_k+\\Delta t\\,v_\\theta(x_k,t_k)$；若用二阶中点法，则先取半步预测再校正，单步需两次前向。末端 latent 送 VAE 解码。","核心公式为直线插值与速度回归：$$x_t=(1-t)x_0+t\\varepsilon,\\qquad \\mathcal{L}=\\mathbb{E}\\|v_\\theta(x_t,t)-(\\varepsilon-x_0)\\|^2$$ 其中 $t$ 为连续时间、$x_0$ 为样本、$\\varepsilon$ 为噪声、$v_\\theta$ 为待学速度场；因速度沿直线恒定，积分误差随步长线性而非高阶累积。","负载配方：请求形态为文生图/图生图的单次 latent 生成，批大小按显存与 SLO 在 1–8 间取；SLO 通常要求单图 8 步内出图。步数从 20 步压到 8 步是常见配置，配合 CFG 批合并把条件与非条件前向拼成一个 batch 以摊薄开销。","部署配方：硬件档位为 Blackwell（如 B200/GB200），并行拓扑以单卡或张量并行覆盖 DiT 主体；量化可叠加 FP8/NVFP4 主体 GEMM；KV 指 latent 与 timestep embedding 缓存，按 batch 与分辨率线性增长。Euler 单次前向、中点法两次前向，需按步数与每步开销权衡。","稳定性技巧与失败模式：直线假设在多物体、文字渲染等复杂条件下不严格成立，少步会丢细节；二阶积分虽降误差但单步成本翻倍；CFG 引导系数过大在少步下易过饱和；步长过大时末端 latent 分布偏移，VAE 解码出现色块或结构崩坏。","与相邻算法的差别：相比 DDIM 的弯曲概率路径与绑定 scheduler，整流流用统一速度场参数化，scheduler 可跨模型复用、工程实现简单；相比一致性模型靠蒸馏把多步压成一步，整流流是训练期重参数化路径，不依赖教师模型，可与少步蒸馏叠加进一步压步数。","适用边界与规模上限：适合 4–8 步的快速出图与跨模型复用 scheduler 的场景；规模上受直线假设限制，超高分辨率与强文本约束下需更多步或蒸馏补偿；论文 paper-rectified-flow-a-marginal-preserving-2022 与 paper-scaling-rectified-flow-transformers-2024 给出机制与扩展证据，具体吞吐数字未给出。"],"anchors":["4–8 步","20 步压到 8 步","2022","2024"],"pitfalls":["少步下多物体与文字场景细节丢失，直线假设不成立导致结构错位，需回退更多步或叠加蒸馏。","二阶中点法每步两次前向，若不加批合并，单图时延反而高于 Euler 大步长配置。","CFG 系数在少步下过大引起过饱和与色彩崩坏，需按步数重调引导强度。"]},{"id":"alg-mx-mixed-precision-dit","name":"DiT MX 混合精度分块","year":2025,"direction":"dir-serving-scheduling","tier":"recent","problem":"统一低精度量化对 DiT 的敏感层伤害大，而统一高精度又吃不满 Blackwell 的 FP4/FP8 吞吐，精度与速度难以兼得。","idea":"按层敏感度分配 MXFP4/MXFP6/MXFP8 混合格式，共享指数做块缩放，敏感层保 FP8、其余走 MXFP4，配合 kernel 内格式切换。","how":"它解决统一低精度量化对 DiT 敏感层伤害大、统一高精度又吃不满 Blackwell FP4/FP8 吞吐的矛盾：需要在精度与速度间按层分配，避免一刀切量化导致的画质退化与算力浪费。 机制按数据流顺序：校准阶段逐层测敏感度，按输出误差排序分配 MXFP4/MXFP6/MXFP8 档位；权重按 32 元素块做 MX 共享指数缩放并打包为对应格式；推理时按层元数据选择 MMA 精度通路，敏感层走 FP8，激活按块在线量化，累加器统一 FP32。 核心公式为 MX 块缩放：$$w_i=\\hat{w}_i\\cdot 2^{e_{\\text{block}}},\\qquad e_{\\text{block}}=\\max_j \\lfloor \\log_2|w_j|\\rfloor$$ 其中 $\\hat{w}_i$ 为块内量化尾数、$e_{\\text{block}}$ 为 32 元素共享指数；共享指数让块内动态范围对齐，对离群值比 per-tensor 量化更鲁棒。","flow":["校准阶段逐层测敏感度，按输出误差排序分配精度档位","权重按 32 元素块做 MX 共享指数缩放，打包为对应格式","推理时按层元数据选择 MMA 精度通路，敏感层走 FP8","激活按块在线量化，累加器统一 FP32","末端反量化回 BF16 送 VAE，避免解码漂移"],"formula":"$$\\hat{W}_{b}=\\text{shared\\_exp}_{b}\\cdot Q_{p}(W_{b}),\\quad \\text{Err}\\approx\\sum_{l}\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}}$$","pros":["敏感层保精度、其余层吃 FP4 吞吐，整体时延降 30–50% 且画质退化可控","MX 块缩放对离群值鲁棒，比 per-tensor 量化稳定"],"cons":["多格式混合让 kernel 分支变多，编译与调优成本高","敏感度排序依赖校准集，换模型或换分辨率需重跑"],"papers":["paper-mixdit-accelerating-image-diffusion-2025","paper-microscaling-data-formats-for-deep-l-2023"],"successors":["alg-feature-cache-rescue"],"facts":["它解决统一低精度量化对 DiT 敏感层伤害大、统一高精度又吃不满 Blackwell FP4/FP8 吞吐的矛盾：需要在精度与速度间按层分配，避免一刀切量化导致的画质退化与算力浪费。","机制按数据流顺序：校准阶段逐层测敏感度，按输出误差排序分配 MXFP4/MXFP6/MXFP8 档位；权重按 32 元素块做 MX 共享指数缩放并打包为对应格式；推理时按层元数据选择 MMA 精度通路，敏感层走 FP8，激活按块在线量化，累加器统一 FP32。","核心公式为 MX 块缩放：$$w_i=\\hat{w}_i\\cdot 2^{e_{\\text{block}}},\\qquad e_{\\text{block}}=\\max_j \\lfloor \\log_2|w_j|\\rfloor$$ 其中 $\\hat{w}_i$ 为块内量化尾数、$e_{\\text{block}}$ 为 32 元素共享指数；共享指数让块内动态范围对齐，对离群值比 per-tensor 量化更鲁棒。","负载配方：请求形态为 DiT 单步前向的批量 latent 生成，批大小按显存与 SLO 取 1–8；SLO 以单图端到端时延计。校准集需覆盖目标分辨率与提示分布，换模型或换分辨率必须重跑敏感度排序，否则档位分配失配。","部署配方：硬件档位为 Blackwell，利用 MXFP4/MXFP6/MXFP8 的 block scale 硬件路径；并行拓扑以单卡为主、大模型走张量并行；量化按层混合，末端反量化回 BF16 送 VAE 以避免解码漂移；KV 指中间激活缓存，低精度后显存占用下降可容纳更大 batch。","稳定性技巧与失败模式：多格式混合让 kernel 分支变多，编译与调优成本高；敏感度排序依赖校准集，分布外提示可能让被判低敏感的层实际误差放大；块缩放对极端 outlier 仍可能溢出，需保留少量 FP8 通道兜底。","与相邻算法的差别：相比统一 FP8 或统一 NVFP4，MX 混合精度按层敏感度分档，敏感层保 FP8、其余吃 FP4 吞吐，整体时延降 30–50% 且画质退化可控；相比 per-tensor 量化，32 元素块共享指数对离群值更稳，但格式切换带来 kernel 碎片化。","适用边界与规模上限：适合 DiT 主体 GEMM 占主导、VAE 解码占比小的服务化场景；规模上限受校准成本与 kernel 分支数约束，层数越多调优越重；论文 paper-mixdit-accelerating-image-diffusion-2025 与 paper-microscaling-data-formats-for-deep-l-2023 给出机制证据，具体吞吐数字未给出。"],"anchors":["32 元素块","30–50%","2025","2023"],"pitfalls":["换模型或换分辨率未重跑敏感度校准，档位分配失配导致敏感层被误压到 FP4，画质明显退化。","多格式 kernel 分支未融合，调度碎片化使实际吞吐低于理论值，小 batch 下开销占比更高。","校准集分布过窄，分布外提示触发 outlier 溢出，块缩放失效引起数值异常。"]},{"id":"alg-fp8-dit-attn","name":"DiT FP8 注意力与GEMM","year":2022,"direction":"dir-vae-latent-codec","tier":"recent","problem":"Blackwell 上 DiT 的 QKV 投影与注意力 GEMM 受 FP16 带宽与 Tensor Core 吞吐限制，显存占用高且单步时延难以压缩，需要在不显著掉点的前提下把算子搬到 FP8。","idea":"用 E4M3 承载权重与激活、E5M2 承载梯度类敏感张量，配合 per-tensor/per-channel scaling 与 Blackwell 原生 FP8 Tensor Core，把 QKV/FFN GEMM 与注意力矩阵乘统一降到 FP8 执行，残差与 LayerNorm 保留 BF16。","how":"它解决 Blackwell 上 DiT 的 QKV 投影与注意力 GEMM 受 FP16 带宽与 Tensor Core 吞吐限制、显存占用高、单步时延难压的问题：目标是在不显著掉点的前提下把算子搬到 FP8，释放原生 FP8 Tensor Core 吞吐。 机制按数据流顺序：VAE latent 与 timestep embedding 以 BF16 进入 DiT block；LayerNorm 输出经动态 per-token scale 量化为 E4M3 写入 QKV 投影 FP8 GEMM；$Q\\cdot K^T$ 与 $\\text{softmax}\\cdot V$ 在 FP8 Tensor Core 执行，softmax 内部 BF16 累加防溢出；FFN 两级 GEMM 同样走 FP8，输出反量化加回 BF16 残差；每 N 步校准 activation scale 写回缓存。 核心公式为缩放量化：$$x_q=\\text{clamp}\\left(\\text{round}\\left(\\frac{x}{s}\\right),-2^{m-1},2^{m-1}-1\\right),\\qquad s=\\frac{\\max|x|}{2^{m-1}}$$ 其中 $x$ 为激活、$s$ 为 per-token 动态 scale、$m$ 为 E4M3 尾数位宽；E4M3 承载权重与激活、E5M2 承载梯度类敏感张量，残差与 LayerNorm 保留 BF16。","flow":["请求进入后，VAE latent 与 timestep embedding 以 BF16 进入 DiT block","LayerNorm 输出经动态 per-token scale 量化为 E4M3，写入 QKV 投影的 FP8 GEMM","Q·K^T 与 softmax·V 在 FP8 Tensor Core 上执行，softmax 内部用 BF16 累加避免溢出","FFN 两级 GEMM 同样走 FP8，输出经反量化加回 BF16 残差","每 N 步校准一次 activation scale，写回 KV/中间缓存供后续 step 复用"],"formula":"$$\\text{FLOPs}_{\\text{eff}} = \\frac{\\text{FLOPs}_{\\text{bf16}}}{2},\\quad \\Delta_{\\text{err}} \\approx \\frac{\\Delta_{\\text{fp8}}}{\\sqrt{N_{\\text{calib}}}},\\quad T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$","pros":["Blackwell FP8 Tensor Core 吞吐约为 BF16 的 2 倍，QKV/FFN GEMM 直接受益，单步时延可降 30%–45%","权重与激活显存减半，KV/中间激活缓存可容纳更大 batch 或更高分辨率 latent"],"cons":["注意力 softmax 与残差对量化误差敏感，需保留 BF16 累加与 outlier 通道，否则 FID 明显退化","per-token 动态 scale 引入额外 reduction kernel，小 batch 下开销占比上升，需与 CUDA Graph 融合"],"papers":["paper-fp8-formats-for-deep-learning-2022","paper-flashattention-3-fast-and-accurate-a-2024"],"successors":["alg-feature-cache-skip"],"facts":["它解决 Blackwell 上 DiT 的 QKV 投影与注意力 GEMM 受 FP16 带宽与 Tensor Core 吞吐限制、显存占用高、单步时延难压的问题：目标是在不显著掉点的前提下把算子搬到 FP8，释放原生 FP8 Tensor Core 吞吐。","机制按数据流顺序：VAE latent 与 timestep embedding 以 BF16 进入 DiT block；LayerNorm 输出经动态 per-token scale 量化为 E4M3 写入 QKV 投影 FP8 GEMM；$Q\\cdot K^T$ 与 $\\text{softmax}\\cdot V$ 在 FP8 Tensor Core 执行，softmax 内部 BF16 累加防溢出；FFN 两级 GEMM 同样走 FP8，输出反量化加回 BF16 残差；每 N 步校准 activation scale 写回缓存。","核心公式为缩放量化：$$x_q=\\text{clamp}\\left(\\text{round}\\left(\\frac{x}{s}\\right),-2^{m-1},2^{m-1}-1\\right),\\qquad s=\\frac{\\max|x|}{2^{m-1}}$$ 其中 $x$ 为激活、$s$ 为 per-token 动态 scale、$m$ 为 E4M3 尾数位宽；E4M3 承载权重与激活、E5M2 承载梯度类敏感张量，残差与 LayerNorm 保留 BF16。","负载配方：请求形态为 DiT 单步前向的批量 latent 生成，批大小按显存与 SLO 取 1–8；SLO 以单图时延计。per-token 动态 scale 引入额外 reduction kernel，小 batch 下开销占比上升，需与 CUDA Graph 融合以摊薄调度成本。","部署配方：硬件档位为 Blackwell，FP8 Tensor Core 吞吐约为 BF16 的 2 倍；并行拓扑以单卡为主、大模型走张量并行；量化用 E4M3 权重与激活、E5M2 敏感张量；KV 指 QKV 与中间激活缓存，权重与激活显存减半后可容纳更大 batch 或更高分辨率 latent。","稳定性技巧与失败模式：注意力 softmax 与残差对量化误差敏感，需保留 BF16 累加与 outlier 通道，否则 FID 明显退化；per-token scale 的 reduction 在小 batch 下拖慢单步；校准间隔过长会让 activation scale 漂移，长序列注意力出现数值溢出。","与相邻算法的差别：相比 BF16 基线，FP8 把 QKV/FFN GEMM 与注意力矩阵乘统一降精度，单步时延降 30%–45%；相比 NVFP4 混合精度，FP8 精度更高、实现更简单，但吞吐只有 FP4 的一半，适合对画质更敏感或 kernel 调优资源有限的场景。","适用边界与规模上限：适合注意力与 FFN GEMM 占主导、显存受限的服务化部署；规模上限受 softmax 数值稳定性与 reduction 开销约束，超长序列与高分辨率下需保留更多 BF16 通道；论文 paper-fp8-formats-for-deep-learning-2022 与 paper-flashattention-3-fast-and-accurate-a-2024 给出格式与注意力证据，具体吞吐数字未给出。"],"anchors":["2 倍","30%–45%","2022","2024"],"pitfalls":["softmax 与残差未保留 BF16 累加，FP8 量化误差累积导致 FID 明显退化与注意力图崩坏。","per-token 动态 scale 的 reduction kernel 未与 CUDA Graph 融合，小 batch 下调度开销吃掉 FP8 收益。","activation scale 校准间隔过长，长序列注意力出现数值溢出，输出 NaN 或色块。"]},{"id":"alg-nvfp4-hybrid-dit","name":"DiT NVFP4 混合精度","year":2024,"direction":"dir-video-streaming","tier":"recent","problem":"DiT 权重与激活在 4bit 下量化误差急剧放大，尤其 timestep embedding 与 attention 输出通道存在显著 outlier，直接 FP4 全量化会导致结构崩坏，需要在 Blackwell NVFP4 上做分层混合精度。","idea":"对 outlier 敏感的层（timestep MLP、attention 输出投影）保留 FP8/BF16，其余线性层用 NVFP4（E2M1 + 两级 micro-block scaling），利用 Blackwell 原生 FP4 Tensor Core 与 block scale 硬件路径。","how":"它解决 DiT 权重与激活在 4bit 下量化误差急剧放大、尤其 timestep embedding 与 attention 输出通道存在显著 outlier、直接 FP4 全量化导致结构崩坏的问题：需要在 Blackwell NVFP4 上做分层混合精度。 机制按数据流顺序：离线分析各层激活的 kurtosis 与 max/mean 比标记高敏感层；高敏感层权重与激活保持 FP8，其余层权重量化为 NVFP4 并存储 block scale；推理时 latent 进入 DiT，按层标签分派到 FP4 或 FP8 GEMM 队列；FP4 输出经 block scale 反量化后与 FP8 分支在 BF16 残差处汇合；VAE 解码前统一回 BF16。 核心公式为两级 micro-block scaling：$$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}},\\qquad \\hat{w}_i\\in\\text{E2M1}$$ 其中 $\\hat{w}_i$ 为 4bit 尾数、$s_{\\text{block}}$ 为块级缩放、$s_{\\text{tensor}}$ 为张量级缩放；两级缩放把 E2M1 的动态范围拉回可用区间，隔离 outlier 层。","flow":["离线分析各层激活的 kurtosis 与 max/mean 比，标记高敏感层","高敏感层权重与激活保持 FP8，其余层权重量化为 NVFP4 并存储 block scale","推理时 latent 进入 DiT，按层标签分派到 FP4 或 FP8 GEMM 队列","FP4 GEMM 输出经 block scale 反量化后与 FP8 分支结果在 BF16 残差处汇合","VAE 解码前统一回到 BF16，避免解码器输入精度断层"],"formula":"$$w_{\\text{nvfp4}} = s_{\\text{blk}} \\cdot \\text{E2M1}(w),\\quad \\text{err}_{\\ell} \\propto \\frac{\\max|a_\\ell|}{\\text{rms}(a_\\ell)},\\quad \\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$","pros":["NVFP4 在 Blackwell 上吞吐为 FP8 的 2 倍，主体 GEMM 可再降一半时延，显存降至 BF16 的 1/4","分层混合精度把 outlier 层隔离，整体 FID 退化可控在 1–2 个点内"],"cons":["层敏感度分析需离线校准集，换模型/换分辨率要重跑，工程链路长","FP4 与 FP8 分支混跑导致 kernel 调度碎片化，需手写融合 kernel 才能兑现理论吞吐"],"papers":["paper-hq-dit-efficient-diffusion-transform-2024","paper-fp4dit-towards-effective-floating-po-2025"],"successors":["alg-stage-serving-pipeline"],"facts":["它解决 DiT 权重与激活在 4bit 下量化误差急剧放大、尤其 timestep embedding 与 attention 输出通道存在显著 outlier、直接 FP4 全量化导致结构崩坏的问题：需要在 Blackwell NVFP4 上做分层混合精度。","机制按数据流顺序：离线分析各层激活的 kurtosis 与 max/mean 比标记高敏感层；高敏感层权重与激活保持 FP8，其余层权重量化为 NVFP4 并存储 block scale；推理时 latent 进入 DiT，按层标签分派到 FP4 或 FP8 GEMM 队列；FP4 输出经 block scale 反量化后与 FP8 分支在 BF16 残差处汇合；VAE 解码前统一回 BF16。","核心公式为两级 micro-block scaling：$$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}},\\qquad \\hat{w}_i\\in\\text{E2M1}$$ 其中 $\\hat{w}_i$ 为 4bit 尾数、$s_{\\text{block}}$ 为块级缩放、$s_{\\text{tensor}}$ 为张量级缩放；两级缩放把 E2M1 的动态范围拉回可用区间，隔离 outlier 层。","负载配方：请求形态为 DiT 单步前向的批量 latent 生成，批大小按显存与 SLO 取 1–8；SLO 以单图端到端时延计。层敏感度分析需离线校准集，换模型或换分辨率要重跑，工程链路长于纯 FP8 方案。","部署配方：硬件档位为 Blackwell，NVFP4 吞吐为 FP8 的 2 倍、显存降至 BF16 的 1/4；并行拓扑以单卡为主、大模型走张量并行；量化分层混合，高敏感层保 FP8/BF16、其余走 NVFP4；KV 指中间激活缓存，低精度后显存大幅下降可容纳更大 batch 或更高分辨率。","稳定性技巧与失败模式：FP4 与 FP8 分支混跑导致 kernel 调度碎片化，需手写融合 kernel 才能兑现理论吞吐；层敏感度分析依赖校准集，分布外提示可能让被判低敏感层误差放大；VAE 解码前未回 BF16 会造成解码器输入精度断层与色彩漂移。","与相邻算法的差别：相比 DiT FP8 注意力与 GEMM，NVFP4 混合精度把主体 GEMM 再降一半时延、显存降至 1/4，但需分层隔离 outlier；相比 MX 混合精度，NVFP4 用 E2M1 加两级 micro-block scaling，精度档位更少、硬件路径更专，调优更依赖融合 kernel。","适用边界与规模上限：适合显存紧张、主体 GEMM 占主导且能承担离线校准与 kernel 调优成本的服务化场景；规模上限受 outlier 层比例与 kernel 碎片化约束，敏感层越多 FP4 收益越小；论文 paper-hq-dit-efficient-diffusion-transform-2024 与 paper-fp4dit-towards-effective-floating-po-2025 给出机制证据，具体吞吐数字未给出。"],"anchors":["2 倍","1/4","1–2 个点","2024","2025"],"pitfalls":["FP4 与 FP8 分支未手写融合 kernel，调度碎片化使实际吞吐远低于理论值。","换模型或换分辨率未重跑层敏感度分析，outlier 层被误压到 NVFP4 导致结构崩坏。","VAE 解码前未统一回 BF16，解码器输入精度断层引起色彩漂移与细节丢失。"]},{"id":"alg-ptq4dit-block-calib","name":"DiT 分块 PTQ 校准","year":2024,"direction":"dir-step-distill-consistency","tier":"recent","problem":"扩散模型多步采样使激活分布随 timestep 漂移，传统一次性 PTQ 校准统计量无法覆盖全轨迹，导致后段 step 量化误差累积、画面出现色偏与结构噪声。","idea":"按 timestep 区间分块采集激活统计，每块独立求 scale/zero-point，并在 block 级做重构误差最小化，把量化参数与采样轨迹对齐。","how":"解决扩散模型多步采样时激活分布随 timestep 漂移的问题：一次性全局 PTQ 校准统计量只覆盖单一 timestep 区间，后段 step 的量化误差沿采样轨迹累积，画面出现色偏与结构噪声。分块校准把量化参数与采样轨迹对齐。 机制按数据流顺序：在校准集上跑完整采样轨迹，按 timestep 分桶记录每层激活的 min/max 与直方图；对每个 timestep 桶求解最小化重构误差的 scale 与 zero-point；把分块量化参数打包进权重旁路表；推理时按当前 timestep 索引查表，GEMM 前用查到的 scale 量化激活。 核心公式为逐桶重构误差最小化：$$\\min_{s,z}\\ \\|W X_t - s\\,(\\mathrm{clamp}(\\lfloor W X_t/s \\rceil + z,\\,q_{\\min},\\,q_{\\max}) - z)\\|_2^2$$，其中 $s$ 为该 timestep 桶的激活 scale，$z$ 为 zero-point，$W X_t$ 为第 $t$ 步该层 GEMM 的浮点参考输出，$q_{\\min},q_{\\max}$ 为量化范围端点。","flow":["在校准集上跑完整采样轨迹，按 timestep 分桶记录每层激活的 min/max 与直方图","对每个 timestep 桶求解最小化重构误差的 scale 与 zero-point","把分块量化参数打包进权重旁路表，推理时按当前 timestep 索引查表","GEMM 前用查到的 scale 量化激活，权重用全局 scale，输出反量化回 BF16","对误差超阈的 block 回退到 FP8 或 BF16 作为兜底"],"formula":"$$s_t^* = \\arg\\min_{s} \\|W x_t - \\text{deq}(\\text{q}(W x_t; s))\\|_2^2,\\quad \\text{err}_{\\text{traj}} = \\sum_{t=1}^{T} \\|\\hat{x}_{t-1} - x_{t-1}\\|_2^2$$","pros":["分 timestep 校准把后段 step 的量化误差压下来，少步采样下 FID 退化显著小于全局 PTQ","查表开销仅一次索引，可与 CUDA Graph 固化，不破坏单步 kernel 流水"],"cons":["校准需覆盖完整采样轨迹，离线成本高，换 sampler/换步数要重校准","分块参数表增加显存与 cache 压力，高分辨率大模型下查表命中率下降"],"papers":["paper-ptq4dit-post-training-quantization-f-2024","paper-vidit-q-efficient-and-accurate-quant-2024"],"successors":["alg-mixed-resolution-serve"],"facts":["解决扩散模型多步采样时激活分布随 timestep 漂移的问题：一次性全局 PTQ 校准统计量只覆盖单一 timestep 区间，后段 step 的量化误差沿采样轨迹累积，画面出现色偏与结构噪声。分块校准把量化参数与采样轨迹对齐。","机制按数据流顺序：在校准集上跑完整采样轨迹，按 timestep 分桶记录每层激活的 min/max 与直方图；对每个 timestep 桶求解最小化重构误差的 scale 与 zero-point；把分块量化参数打包进权重旁路表；推理时按当前 timestep 索引查表，GEMM 前用查到的 scale 量化激活。","核心公式为逐桶重构误差最小化：$$\\min_{s,z}\\ \\|W X_t - s\\,(\\mathrm{clamp}(\\lfloor W X_t/s \\rceil + z,\\,q_{\\min},\\,q_{\\max}) - z)\\|_2^2$$，其中 $s$ 为该 timestep 桶的激活 scale，$z$ 为 zero-point，$W X_t$ 为第 $t$ 步该层 GEMM 的浮点参考输出，$q_{\\min},q_{\\max}$ 为量化范围端点。","负载配方：请求形态为文生图/图生图单条或小批，批大小受分块参数表显存约束，通常取 1–8；SLO 以单请求端到端时延为主，少步采样（4–8 步）下查表开销仅一次索引，可与 CUDA Graph 固化，不破坏单步 kernel 流水。","部署配方：硬件档位为支持 FP8/FP4 的 GPU；量化上权重用全局 scale、激活按 timestep 查表分块 scale；并行拓扑以单卡或张量并行为主，分块参数表随层数线性增长，高分辨率大模型下查表命中率下降、cache 压力上升。","稳定性技巧：对重构误差超阈的 block 回退到 FP8 或 BF16 作为兜底，避免个别层量化误差主导画面；校准需覆盖完整采样轨迹，换 sampler 或换步数必须重校准，否则桶边界与轨迹错位导致后段误差反弹。","与相邻算法的差别：全局 PTQ 只求一组 scale/zero-point，分块 PTQ 按 timestep 桶各求一组并查表；与 QAT 相比不做梯度反传、离线成本低，但校准轨迹覆盖要求更高；与 FP8 动态量化相比，分块表是离线静态的，推理时无额外归约开销。","适用边界与规模上限：适合少步采样（4–8 步）且 timestep 桶数有限的 DiT；步数增多、桶数细化会线性放大校准离线成本与参数表显存；高分辨率大模型下查表命中率下降，需配合 block 级回退；换底座模型或 sampler 需重校准，规模上限受校准算力与显存约束。"],"anchors":["2024","paper-ptq4dit-post-training-quantization-f-2024","paper-vidit-q-efficient-and-accurate-quant-2024"],"pitfalls":["换 sampler 或改采样步数后未重校准，timestep 桶边界与真实轨迹错位，后段 step 量化误差重新累积，画面出现色偏与结构噪声。","分块参数表随层数与桶数线性增长，高分辨率大模型下显存与 cache 压力上升、查表命中率下降，未设 block 级 FP8/BF16 回退时个别层误差主导输出。","校准集只覆盖短轨迹或单一 prompt 分布，桶内 min/max 统计偏窄，推理遇到长尾激活时 clamp 截断严重，GEMM 输出失真。"]},{"id":"alg-lcm-few-step","name":"LCM 少步一致性采样","year":2023,"direction":"dir-dit-quantization","tier":"recent","problem":"标准 DDPM/DDIM 需 20–50 步才能出图，服务端单请求时延被步数线性放大，GPU 时间片被长尾请求占满，SLO 难以满足。","idea":"在 latent 空间用一致性蒸馏把多步 ODE 轨迹压到 2–8 步，学生模型在任意 timestep 直接预测 x0，配合 scheduler 跳步实现少步高质量采样。","how":"解决标准 DDPM/DDIM 需 20–50 步才能出图的问题：服务端单请求时延被步数线性放大，GPU 时间片被长尾请求占满，SLO 难以满足；一致性蒸馏把多步 ODE 轨迹压到 2–8 步。 机制按数据流顺序：离线用教师模型跑完整轨迹采集 $(x_t,t,x_0)$ 三元组；训练学生网络满足同一条轨迹上任意两点预测的 $x_0$ 一致；部署时 latent 从纯噪声出发，按 4–8 个离散 timestep 迭代，每步学生网络直接输出 $x_0$ 估计，scheduler 用跳步公式推进到下一 timestep，末步 $x_0$ 送入 VAE 解码。 核心公式为自一致性约束：$$f_\\theta(x_t,t) \\approx f_\\theta\\big(x_{t'},\\,t'\\big),\\quad x_{t'} = \\text{scheduler\\_step}\\big(f_\\theta(x_t,t),\\,t\\to t'\\big)$$，其中 $f_\\theta$ 为学生网络直接预测的 $x_0$，$t'$ 为轨迹上更靠近数据的相邻 timestep，一致性损失约束两点预测收敛到同一 $x_0$。","flow":["离线阶段用教师模型跑完整轨迹，采集 (x_t, t, x_0) 三元组","训练学生网络满足自一致性：同一条轨迹上任意两点预测的 x0 一致","部署时请求进入，latent 从纯噪声出发，按 4–8 个离散 timestep 迭代","每步学生网络直接输出 x0 估计，scheduler 用跳步公式推进到下一 timestep","末步 x0 送入 VAE 解码，返回图像"],"formula":"$$\\mathcal{L}_{\\text{cons}} = \\mathbb{E}_{t_1,t_2}\\left[\\|f_\\theta(x_{t_1},t_1) - f_{\\theta^-}(x_{t_2},t_2)\\|_2^2\\right],\\quad T_{\\text{req}} \\approx N_{\\text{step}}\\cdot T_{\\text{step}},\\ N_{\\text{step}}\\in[2,8]$$","pros":["步数从数十步压到个位数，单请求时延近似线性下降，吞吐成倍提升","学生模型可直接复用原 DiT 结构，部署链路改动小，易与 FP8/FP4 量化叠加"],"cons":["少步采样牺牲细节与多样性，复杂 prompt 下语义对齐变差，需按业务分层使用","蒸馏训练需教师轨迹数据，换底座模型要重蒸馏，且对 CFG scale 敏感"],"papers":["paper-latent-consistency-models-synthesizi-2023","paper-consistency-models-2023"],"successors":["alg-fa3-blackwell-attn"],"facts":["解决标准 DDPM/DDIM 需 20–50 步才能出图的问题：服务端单请求时延被步数线性放大，GPU 时间片被长尾请求占满，SLO 难以满足；一致性蒸馏把多步 ODE 轨迹压到 2–8 步。","机制按数据流顺序：离线用教师模型跑完整轨迹采集 $(x_t,t,x_0)$ 三元组；训练学生网络满足同一条轨迹上任意两点预测的 $x_0$ 一致；部署时 latent 从纯噪声出发，按 4–8 个离散 timestep 迭代，每步学生网络直接输出 $x_0$ 估计，scheduler 用跳步公式推进到下一 timestep，末步 $x_0$ 送入 VAE 解码。","核心公式为自一致性约束：$$f_\\theta(x_t,t) \\approx f_\\theta\\big(x_{t'},\\,t'\\big),\\quad x_{t'} = \\text{scheduler\\_step}\\big(f_\\theta(x_t,t),\\,t\\to t'\\big)$$，其中 $f_\\theta$ 为学生网络直接预测的 $x_0$，$t'$ 为轨迹上更靠近数据的相邻 timestep，一致性损失约束两点预测收敛到同一 $x_0$。","负载配方：请求形态为在线文生图，批大小按显存与 4–8 步迭代组织；SLO 以单请求端到端时延为主，步数从数十步压到个位数使时延近似线性下降、吞吐成倍提升；学生模型复用原 DiT 结构，部署链路改动小。","部署配方：硬件档位为单卡或张量并行 GPU；量化可与 FP8/FP4 叠加，学生网络结构与原 DiT 一致便于复用现有量化方案；显存按 4–8 步迭代的激活峰值配置，无需保留教师轨迹数据在推理侧。","稳定性技巧：对 CFG scale 敏感，需按业务分层固定 guidance 区间；少步采样牺牲细节与多样性，复杂 prompt 下语义对齐变差，应按业务分层使用；换底座模型要重蒸馏，教师轨迹数据需覆盖目标 timestep 网格。","与相邻算法的差别：DDIM 仍需 20–50 步沿弯曲概率流积分；LCM 用一致性蒸馏把轨迹压到 2–8 步且学生网络直接预测 $x_0$；与整流流匹配相比，LCM 是蒸馏而非重参数化训练，步数更少但多样性损失更明显。","适用边界与规模上限：适合对时延敏感、可接受细节与多样性折损的在线服务；复杂 prompt 与高分辨率场景下语义对齐变差，需按业务分层；换底座模型要重蒸馏，规模上限受教师轨迹采集成本与蒸馏训练算力约束。"],"anchors":["2023","paper-latent-consistency-models-synthesizi-2023","paper-consistency-models-2023"],"pitfalls":["复杂 prompt 下少步采样语义对齐变差、细节与多样性折损，若未按业务分层使用，长尾请求画质不达标引发重试放大 GPU 时间片占用。","对 CFG scale 敏感，guidance 区间漂移时学生网络 $x_0$ 预测偏离轨迹，画面出现过饱和或结构崩坏，且难以从单步日志定位。","换底座模型未重蒸馏，教师轨迹与新底座分布错位，一致性约束失效，少步输出退化为模糊纹理。"]},{"id":"alg-flow-matching-sampler","name":"整流流匹配采样器","year":2022,"direction":"dir-cache-sparsity","tier":"recent","problem":"扩散采样沿弯曲概率流积分，数值求解需小步长与多步数，且离散化误差随步数减少迅速放大，服务端难以在少步下保持画质。","idea":"用整流流把噪声到数据的传输拉直为近似直线轨迹，训练速度场 v_θ 拟合直线插值，推理时用 Euler/中点法沿直线积分，少步即可高保真。","how":"解决扩散采样沿弯曲概率流积分的问题：数值求解需小步长与多步数，离散化误差随步数减少迅速放大，服务端难以在少步下保持画质；整流流把噪声到数据的传输拉直为近似直线轨迹。 机制按数据流顺序：请求进入，latent 从标准高斯采样，timestep 从 1 递减到 0；条件 embedding 与 latent 拼接送入 DiT，网络输出速度场 $v_\\theta(x_t,t,c)$；Euler 更新或中点法做二阶修正；按 scheduler 离散 timestep 表迭代 4–20 步；终态 $x_0$ 送入 VAE 解码输出图像。 核心公式为直线插值速度场拟合与 Euler 积分：$$x_t = (1-t)\\,x_0 + t\\,\\epsilon,\\quad v_\\theta(x_t,t,c)\\approx \\epsilon - x_0,\\quad x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta(x_t,t,c)$$，其中 $x_0$ 为数据样本，$\\epsilon$ 为标准高斯噪声，$t\\in[0,1]$ 为插值系数，$\\Delta$ 为离散步长。","flow":["请求进入，latent 从标准高斯采样，timestep 从 1 递减到 0","条件 embedding 与 latent 拼接送入 DiT，网络输出速度场 v_θ(x_t,t,c)","Euler 更新 x_{t-Δ} = x_t − Δ·v_θ，或中点法做二阶修正","按 scheduler 的离散 timestep 表迭代 4–20 步","终态 x_0 送入 VAE 解码输出图像"],"formula":"$$x_t = (1-t)\\,x_0 + t\\,\\epsilon,\\quad \\frac{dx_t}{dt} = v_\\theta(x_t,t),\\quad x_{t-\\Delta} = x_t - \\Delta\\,v_\\theta(x_t,t)$$","pros":["直线轨迹使少步 Euler 离散误差小，4–8 步即可接近多步 DDIM 画质","速度场参数化与 CFG 合并天然兼容，训练目标简单、收敛稳定"],"cons":["直线化依赖训练分布，复杂条件/高分辨率下轨迹仍有弯曲，少步会出现纹理模糊","二阶求解器增加每步前向次数，时延与显存开销上升，需按 SLO 权衡"],"papers":["paper-flow-matching-for-generative-modelin-2022","paper-scaling-rectified-flow-transformers-2024"],"successors":["alg-lcm-fewstep"],"facts":["解决扩散采样沿弯曲概率流积分的问题：数值求解需小步长与多步数，离散化误差随步数减少迅速放大，服务端难以在少步下保持画质；整流流把噪声到数据的传输拉直为近似直线轨迹。","机制按数据流顺序：请求进入，latent 从标准高斯采样，timestep 从 1 递减到 0；条件 embedding 与 latent 拼接送入 DiT，网络输出速度场 $v_\\theta(x_t,t,c)$；Euler 更新或中点法做二阶修正；按 scheduler 离散 timestep 表迭代 4–20 步；终态 $x_0$ 送入 VAE 解码输出图像。","核心公式为直线插值速度场拟合与 Euler 积分：$$x_t = (1-t)\\,x_0 + t\\,\\epsilon,\\quad v_\\theta(x_t,t,c)\\approx \\epsilon - x_0,\\quad x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta(x_t,t,c)$$，其中 $x_0$ 为数据样本，$\\epsilon$ 为标准高斯噪声，$t\\in[0,1]$ 为插值系数，$\\Delta$ 为离散步长。","负载配方：请求形态为在线文生图，批大小按显存与 4–20 步迭代组织；SLO 以单请求时延为主，4–8 步 Euler 即可接近多步 DDIM 画质；二阶中点法增加每步前向次数，时延与显存开销上升，需按 SLO 权衡。","部署配方：硬件档位为单卡或张量并行 GPU；量化可与 FP8/FP4 叠加，速度场参数化与 CFG 合并天然兼容；显存按 4–20 步迭代的激活峰值配置，二阶求解器需保留中间量做修正。","稳定性技巧：直线化依赖训练分布，复杂条件/高分辨率下轨迹仍有弯曲，少步会出现纹理模糊，需按分辨率与 prompt 复杂度分层选步数；二阶求解器增加每步前向次数，需按 SLO 在步数与阶数间权衡。","与相邻算法的差别：DDIM 沿弯曲概率流积分、少步离散化误差大；整流流匹配用直线插值重参数化速度场，少步 Euler 误差小；与 LCM 一致性蒸馏相比，整流流是训练目标重参数化而非蒸馏，无需教师轨迹数据，但少步画质依赖训练分布直线化程度。","适用边界与规模上限：适合 4–20 步、条件复杂度中等的在线服务；复杂条件/高分辨率下轨迹弯曲，少步出现纹理模糊，需增加步数或改用二阶求解器；规模上限受每步前向次数与显存峰值约束，二阶求解器时延开销更高。"],"anchors":["2022","paper-flow-matching-for-generative-modelin-2022","paper-scaling-rectified-flow-transformers-2024"],"pitfalls":["复杂条件或高分辨率下训练分布直线化不足，轨迹仍弯曲，4–8 步 Euler 输出纹理模糊，未按分辨率与 prompt 复杂度分层选步数时画质不达标。","二阶中点法每步前向次数翻倍，时延与显存开销上升，未按 SLO 权衡阶数与步数时单请求时延超出预算。","速度场与 CFG 合并顺序错位或 guidance scale 漂移，直线插值假设被破坏，少步输出出现结构噪声与语义偏离。"]},{"id":"alg-feature-cache-rescue","name":"特征缓存与动态救援","year":2026,"direction":"dir-serving-scheduling","tier":"recent","problem":"扩散多步采样中相邻 step 的 DiT block 输出高度相似，全量重算浪费算力；但盲目缓存会在语义切换处引入漂移，画质与一致性双损。","idea":"按 block 输出与上一步的相似度决定复用，相似度高则跳过该 block 计算直接取缓存；检测到局部差异超阈时触发动态救援，只重算差异 block 并修正残差。","how":"该算法针对扩散多步采样中相邻 step 的 DiT block 输出高度相似、全量重算浪费算力的问题；同时解决盲目缓存会在语义切换处引入漂移、导致画质与一致性双损的矛盾，目标是在不重训练的前提下降低单步时延。 机制按数据流顺序执行：step t 开始时对每个 DiT block 计算其输入与缓存键的余弦相似度；相似度超阈的 block 跳过前向、直接读取上一步输出缓存；相似度低的 block 标记为救援对象进入重算队列；重算输出与缓存做残差修正后写回缓存；全部 block 汇聚后进入 scheduler 更新 latent。 相似度判定核心公式为 $$s_i=\\cos(\\mathbf{k}_i^{t},\\mathbf{k}_i^{t-1})=\\frac{\\mathbf{k}_i^{t}\\cdot\\mathbf{k}_i^{t-1}}{\\lVert\\mathbf{k}_i^{t}\\rVert\\,\\lVert\\mathbf{k}_i^{t-1}\\rVert}$$，其中 $\\mathbf{k}_i^{t}$ 为第 $i$ 个 block 在第 $t$ 步的缓存键；当 $s_i>\\tau$ 时复用缓存，否则进入救援队列重算，$\\tau$ 为相似度阈值。","flow":["step t 开始时，对每个 DiT block 计算输入与缓存键的余弦相似度","相似度超阈的 block 跳过前向，直接读取上一步输出缓存","相似度低的 block 标记为救援对象，进入重算队列","重算 block 的输出与缓存做残差修正，写回缓存供下一步复用","全部 block 汇聚后进入 scheduler 更新 latent"],"formula":"$$\\text{reuse}_\\ell = \\mathbb{1}\\left[\\cos(h_\\ell^t, h_\\ell^{t-1}) > \\tau\\right],\\quad T_{\\text{step}} \\approx \\sum_{\\ell} \\left(1-\\text{reuse}_\\ell\\right) T_\\ell + T_{\\text{cache}}$$","pros":["相似 block 跳过计算，单步时延可降 20%–40%，且无需重训练","动态救援把漂移限制在局部 block，画质退化小于固定间隔缓存"],"cons":["相似度判定与救援调度引入分支，破坏 kernel 规整性，需 CUDA Graph 分段捕获","缓存占用显存，高分辨率大 DiT 下与 KV/激活争抢，batch 容量受限"],"papers":["paper-ladr-locality-aware-dynamic-rescue-f-2026","paper-corgi-contribution-guided-block-wise-2025"],"successors":[],"facts":["该算法针对扩散多步采样中相邻 step 的 DiT block 输出高度相似、全量重算浪费算力的问题；同时解决盲目缓存会在语义切换处引入漂移、导致画质与一致性双损的矛盾，目标是在不重训练的前提下降低单步时延。","机制按数据流顺序执行：step t 开始时对每个 DiT block 计算其输入与缓存键的余弦相似度；相似度超阈的 block 跳过前向、直接读取上一步输出缓存；相似度低的 block 标记为救援对象进入重算队列；重算输出与缓存做残差修正后写回缓存；全部 block 汇聚后进入 scheduler 更新 latent。","相似度判定核心公式为 $$s_i=\\cos(\\mathbf{k}_i^{t},\\mathbf{k}_i^{t-1})=\\frac{\\mathbf{k}_i^{t}\\cdot\\mathbf{k}_i^{t-1}}{\\lVert\\mathbf{k}_i^{t}\\rVert\\,\\lVert\\mathbf{k}_i^{t-1}\\rVert}$$，其中 $\\mathbf{k}_i^{t}$ 为第 $i$ 个 block 在第 $t$ 步的缓存键；当 $s_i>\\tau$ 时复用缓存，否则进入救援队列重算，$\\tau$ 为相似度阈值。","负载配方：请求形态为多步扩散采样，按分辨率与步数分桶；批大小受缓存显存占用约束，高分辨率大 DiT 下缓存与 KV/激活争抢显存，batch 容量受限；SLO 以单步时延为目标，材料给出单步时延可降 20%–40%，具体批大小与 SLO 数值未给出。","部署配方：硬件档位与并行拓扑材料未给出；量化方案材料未给出；缓存占用显存是主要容量约束，需与 KV/激活统一规划显存预算；相似度判定与救援调度引入分支，破坏 kernel 规整性，需 CUDA Graph 分段捕获以维持执行效率。","稳定性技巧：用动态救援把漂移限制在局部 block，只重算差异 block 并做残差修正，使画质退化小于固定间隔缓存；失败模式包括阈值设置不当导致语义切换处漏救援、分支导致 CUDA Graph 捕获断裂、以及缓存显存挤占使 batch 容量下降。","与相邻算法的差别：区别于固定间隔缓存（按固定 step 周期复用、不检测相似度），本算法按 block 输出与上一步的相似度逐 block 决定复用，并引入救援队列只重算差异 block；也区别于步数蒸馏与一致性模型，后者改变采样轨迹与步数，本算法不重训练、只改单步内计算路径。","适用边界与规模上限：适用于相邻 step 输出相似度高、语义切换稀疏的多步扩散采样；无需重训练是其主要优势；规模上限受缓存显存约束，高分辨率大 DiT 下与 KV/激活争抢显存使 batch 容量受限，单步时延收益为 20%–40%，超出该范围的收益材料未给出。"],"anchors":["20%–40%","2026","2025"],"pitfalls":["相似度阈值设置过松会在语义切换处漏掉救援，缓存输出直接进入 scheduler，造成画面局部漂移与跨 step 一致性下降。","相似度判定与救援调度引入分支，破坏 kernel 规整性，若未做 CUDA Graph 分段捕获，会出现捕获失败或重放错误，单步时延收益被抵消。","缓存占用显存，高分辨率大 DiT 下与 KV/激活争抢显存预算，导致 batch 容量受限，吞吐不升反降。"]},{"id":"alg-mixed-res-serve","name":"混合分辨率补丁调度","year":2025,"direction":"dir-vae-latent-codec","tier":"recent","problem":"高分辨率请求的 DiT 计算量随像素平方增长，与低分辨率请求混跑时 GPU batch 被大请求拖慢，小请求 SLO 被长尾拖垮，整体吞吐下降。","idea":"把图像切成 patch，按 patch 分辨率与请求 SLO 分级调度：低分辨率 patch 走小 batch 快通道，高分辨率 patch 走大 batch 慢通道，patch 级队列动态匹配 GPU 资源。","how":"该算法解决高分辨率请求 DiT 计算量随像素平方增长、与低分辨率请求混跑时 GPU batch 被大请求拖慢、小请求 SLO 被长尾拖垮、整体吞吐下降的问题。 机制按数据流顺序执行：请求进入后按目标分辨率切分为 patch 集合并标注 SLO 等级；patch 调度器按分辨率与 SLO 把 patch 分配到快/慢通道队列；快通道用小 batch 低延迟 kernel，慢通道用大 batch 高吞吐 kernel；各通道独立采样去噪，patch 结果写回请求级缓冲区；全部 patch 完成后拼接、VAE 解码并返回图像。 计算量关系为 $$C\\propto H\\times W$$，其中 $C$ 为 DiT 计算量，$H,W$ 为图像高宽；patch 级调度把大请求拆为 patch 集合，使快通道小 batch 与慢通道大 batch 的 kernel 形状更规整，Tensor Core 利用率高于混 batch。","flow":["请求进入后按目标分辨率切分为 patch 集合，标注 SLO 等级","patch 调度器按分辨率与 SLO 把 patch 分配到快/慢通道队列","快通道用小 batch 低延迟 kernel，慢通道用大 batch 高吞吐 kernel","各通道独立采样去噪，patch 结果写回请求级缓冲区","全部 patch 完成后拼接、VAE 解码并返回图像"],"formula":"$$\\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}},\\quad \\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$","pros":["patch 级调度让大小请求共享 GPU 而不互相阻塞，混合负载下吞吐与 SLO 同时改善","分辨率分级使 kernel 形状更规整，Tensor Core 利用率高于混 batch"],"cons":["patch 切分与拼接引入边界伪影，需重叠 patch 与融合后处理，增加显存与算力","patch 级队列与拼接逻辑复杂，请求级尾延迟受最慢 patch 支配，调度需谨慎"],"papers":["paper-patchedserve-a-patch-management-fram-2025","paper-genserve-efficient-co-serving-of-het-2026"],"successors":[],"facts":["该算法解决高分辨率请求 DiT 计算量随像素平方增长、与低分辨率请求混跑时 GPU batch 被大请求拖慢、小请求 SLO 被长尾拖垮、整体吞吐下降的问题。","机制按数据流顺序执行：请求进入后按目标分辨率切分为 patch 集合并标注 SLO 等级；patch 调度器按分辨率与 SLO 把 patch 分配到快/慢通道队列；快通道用小 batch 低延迟 kernel，慢通道用大 batch 高吞吐 kernel；各通道独立采样去噪，patch 结果写回请求级缓冲区；全部 patch 完成后拼接、VAE 解码并返回图像。","计算量关系为 $$C\\propto H\\times W$$，其中 $C$ 为 DiT 计算量，$H,W$ 为图像高宽；patch 级调度把大请求拆为 patch 集合，使快通道小 batch 与慢通道大 batch 的 kernel 形状更规整，Tensor Core 利用率高于混 batch。","负载配方：请求形态为混合分辨率请求，按目标分辨率切分为 patch 并标注 SLO 等级；快通道用小 batch、慢通道用大 batch，具体批大小未给出；SLO 按请求等级标注并驱动 patch 分通道，具体 SLO 数值未给出。","部署配方：硬件档位与并行拓扑材料未给出；量化与 KV 方案材料未给出；核心部署决策是 patch 级队列动态匹配 GPU 资源，快/慢通道使用不同 batch 与 kernel 形状，各通道独立采样去噪。","稳定性技巧：用重叠 patch 与融合后处理抑制边界伪影；失败模式包括 patch 切分与拼接引入边界伪影、请求级尾延迟受最慢 patch 支配、patch 级队列与拼接逻辑复杂导致调度失误。","与相邻算法的差别：区别于按请求整体调度的服务方案，本算法在 patch 级按分辨率与 SLO 分级调度，让大小请求共享 GPU 而不互相阻塞；也区别于扩散流水线分阶段服务，后者按 stage 拆分 DiT/VAE/后处理，本算法在采样阶段内部按 patch 分流。","适用边界与规模上限：适用于高低分辨率混合负载、小请求 SLO 易被长尾拖垮的场景；规模上限受 patch 切分与拼接开销约束，重叠 patch 增加显存与算力，请求级尾延迟受最慢 patch 支配，具体规模数值未给出。"],"anchors":["2025","2026"],"pitfalls":["patch 切分与拼接引入边界伪影，若重叠 halo 不足或融合后处理不当，拼接处出现接缝与色彩断层。","请求级尾延迟受最慢 patch 支配，慢通道大 batch 排队时单个 patch 拖垮整个请求的 SLO。","patch 级队列与拼接逻辑复杂，快/慢通道负载失衡时 GPU 资源匹配失效，吞吐与 SLO 同时受损。"]},{"id":"alg-vae-tiled-decode","name":"VAE 分块解码与流水","year":2021,"direction":"dir-video-streaming","tier":"classic","problem":"高分辨率 latent 送入 VAE 解码时，单次上采样激活显存峰值可达数十 GB，触发 OOM 或被迫降 batch，解码阶段成为服务端显存与吞吐瓶颈。","idea":"把 latent 按空间切块，逐块过 VAE 解码器并在通道维拼接，块间用重叠 halo 消除边界伪影；解码与 DiT 采样流水重叠，隐藏解码时延。","how":"该算法解决高分辨率 latent 送入 VAE 解码时单次上采样激活显存峰值可达数十 GB、触发 OOM 或被迫降 batch、使解码阶段成为服务端显存与吞吐瓶颈的问题。 机制按数据流顺序执行：DiT 采样完成，latent 写入显存缓冲区；按 tile 尺寸切分 latent，块间保留 halo 重叠区；逐块送入 VAE 解码器上采样，输出写入输出缓冲区对应位置；重叠区做加权融合消除块边界接缝；解码与下一请求的 DiT 采样在不同 stream 上流水重叠。 分块解码的显存峰值关系为 $$M_{\\text{peak}}\\approx M_{\\text{tile}}+M_{\\text{halo}}$$，其中 $M_{\\text{tile}}$ 为单 tile 解码激活显存、$M_{\\text{halo}}$ 为重叠区额外显存；分块把解码显存峰值降到单 tile 量级，高分辨率请求不再 OOM。","flow":["DiT 采样完成，latent 写入显存缓冲区","按 tile 尺寸切分 latent，块间保留 halo 重叠区","逐块送入 VAE 解码器上采样，输出写入输出缓冲区对应位置","重叠区做加权融合，消除块边界接缝","解码与下一请求的 DiT 采样在不同 stream 上流水重叠"],"formula":"$$M_{\\text{peak}} \\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}} + M_{\\text{halo}},\\quad T_{\\text{decode}} \\approx \\sum_{i} T_{\\text{tile},i} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$$","pros":["分块把解码显存峰值降到单 tile 量级，高分辨率请求不再 OOM，batch 容量提升","解码与采样流水重叠，端到端时延中解码部分被隐藏，吞吐提升"],"cons":["halo 重叠与融合引入额外计算与边界伪影风险，tile 尺寸需按模型调参","分块解码 kernel 形状小、launch 频繁，GPU 利用率低于整图解码，需融合 kernel"],"papers":["paper-high-resolution-image-synthesis-with-2021","paper-dc-gen-post-training-diffusion-accel-2025"],"successors":["alg-nvfp4-hybrid-dit"],"facts":["该算法解决高分辨率 latent 送入 VAE 解码时单次上采样激活显存峰值可达数十 GB、触发 OOM 或被迫降 batch、使解码阶段成为服务端显存与吞吐瓶颈的问题。","机制按数据流顺序执行：DiT 采样完成，latent 写入显存缓冲区；按 tile 尺寸切分 latent，块间保留 halo 重叠区；逐块送入 VAE 解码器上采样，输出写入输出缓冲区对应位置；重叠区做加权融合消除块边界接缝；解码与下一请求的 DiT 采样在不同 stream 上流水重叠。","分块解码的显存峰值关系为 $$M_{\\text{peak}}\\approx M_{\\text{tile}}+M_{\\text{halo}}$$，其中 $M_{\\text{tile}}$ 为单 tile 解码激活显存、$M_{\\text{halo}}$ 为重叠区额外显存；分块把解码显存峰值降到单 tile 量级，高分辨率请求不再 OOM。","负载配方：请求形态为高分辨率 latent 解码请求；批大小受 tile 尺寸与 halo 显存约束，分块后 batch 容量提升，具体批大小未给出；SLO 关注端到端时延，解码与采样流水重叠使解码部分被隐藏，具体 SLO 数值未给出。","部署配方：硬件档位与并行拓扑材料未给出；量化与 KV 方案材料未给出；部署要点是 tile 尺寸需按模型调参、解码与 DiT 采样在不同 stream 上流水重叠、分块解码 kernel 形状小且 launch 频繁需融合 kernel。","稳定性技巧：用重叠 halo 与加权融合抑制块边界接缝；失败模式包括 halo 重叠与融合引入额外计算与边界伪影风险、tile 尺寸调参不当导致伪影或显存回升、分块 kernel 形状小 launch 频繁使 GPU 利用率低于整图解码。","与相邻算法的差别：区别于整图一次性 VAE 解码（显存峰值高、易 OOM），本算法按空间切块逐块解码并在通道维拼接；也区别于扩散流水线分阶段服务，后者把 VAE 解码拆为独立 stage，本算法在解码内部做分块与流水重叠。","适用边界与规模上限：适用于高分辨率 latent 解码、整图解码显存峰值达数十 GB 的场景；规模上限受 tile 尺寸与 halo 开销约束，halo 重叠增加显存与算力，分块 kernel 利用率低于整图解码，具体规模数值未给出。"],"anchors":["2021","2025","数十 GB"],"pitfalls":["halo 重叠区不足或加权融合参数不当，块边界出现接缝与亮度跳变，高分辨率图像伪影明显。","tile 尺寸调参不当，过大的 tile 使显存峰值回升触发 OOM，过小的 tile 使 kernel launch 频繁、GPU 利用率下降。","解码与 DiT 采样流水重叠时 stream 同步或显存缓冲区复用出错，导致解码读到未写完的 latent 或输出缓冲区竞争。"]}];})();
